COLLDATA("tadabburar","ar",[[1,"§الفاتحة\nwords\nبِسْمِ اللَّهِأَيْ: أَبْتَدِئُ قِرَاءَتِي مُسْتَعِينًا بِاسْمِ اللهِ.\nالْعَالَمِينَكُلِّ مَنْ سِوَى اللهِ تَعَالَى.\nإِيَّاكَ نَعْبُدُلاَ نَعْبُدُ إِلاَّ أَنْتَ.\ndeeds\nادع الله، وابدأ الدعاء بالحمد والثناء عليه سبحانه كما ابتدأت سورة الفاتحة، ثم اسأله ما تريد كما ختمت السورة، ﴿ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾ ﴿ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ﴾.\nسورة الفاتحة أعظم سورة في القرآن وأكثر سورة تقرأها، اقرأ تفسيرها من أحد التفاسير وأكثر من تدبر آياتها، ﴿بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾ الآيات. إلى آخر السورة.\nحدد مجموعة من أهل الخير والصلاح وأكثر من مصاحبتهم ومجالستهم، ﴿صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ﴾.\nguid\nهذه السورة مقسمة بين الله وعبده؛ فـ﴿إِيَّاكَ نَعۡبُدُ﴾ مع ما قبلها لله، ﴿وَإِيَّاكَ نَسۡتَعِينُ﴾ مع ما بعدها للعبد، فتأمل؛ ﴿إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ﴾.\nلن تعبد الله حق العبادة حتى يعينك الله على ذلك.\nالحذر من اتباع منهج اليهود: تقديم الهوى على الشرع ﴿غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ﴾، ومن منهج النصارى: العبادة بالبدعة والجهل ﴿وَلَا ٱلضَّآلِّينَ﴾.\nrefl\nٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٢ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ٣ مَٰلِكِ يَوۡمِ ٱلدِّينِ ٤\nكأنه سبحانه يقول: يا عبادي إن كنتم تحمدون وتعظمون للكمال الذاتي والصفاتي فاحمدوني فإني أنا (الله)، وإن كان للإحسان والتربية والإنعام فإني أنا ﴿رَبِّ ٱلۡعَٰلَمِينَ﴾، وإن كان للرجاء والطمع في المستقبل فإني أنا ﴿ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ﴾، وإن كان للخوف فإني أنا ﴿مَٰلِكِ يَوۡمِ ٱلدِّينِ﴾. الألوسي: ١/٨٦.\nما دلالة الأوصاف الأربعة في بداية سورة الفاتحة على الحمد لله؟\nبِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ١ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٢ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ٣ مَٰلِكِ يَوۡمِ ٱلدِّينِ ٤ إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ ٥ ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ ٦\nلما كان سؤال الله الهداية إلى الصراط المستقيم أجلّ المطالب ونيله أشرف المواهب علّم الله عباده كيفية سؤاله، وأمرهم أن يقدموا بين يديه حمده والثناء عليه، وتمجيده ثم ذكر عبوديتهم وتوحيدهم، فهاتان وسيلتان إلى مطلوبهم: توسل إليه بأسمائه وصفاته، وتوسل إليه بعبوديته. وهاتان الوسيلتان لا يكاد يرد معهما الدعاء. ابن القيم: ١/٣٦.\nذكرت في الآيات وسيلتان لاستجابة الدعاء، ما هما؟\nإِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ ٥\nذكر الاستعانة بعد العبادة مع دخولها فيها لاحتياج العبد في جميع عباداته إلى الاستعانة بالله تعالى؛ فإن لم يعنه الله لم يحصل له ما يريده من فعل الأوامر واجتناب النواهي. السعدي: ٣٩.\nالاستعانة نوع من أنواع العبادة، فلماذا أفردها الله بالذكر بعد ذكر العبادة الشاملة للاستعانة وغيرها؟\nإِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ ٥\nالعبادة أعلى مراتب الخضوع ولا يجوز شرعًا ولا عقلًا فعلها إلا لله تعالى لأنه المستحق لذلك لكونه موليًا لأعظم النعم من الحياة والوجود وتوابعهما. الألوسي: ١/٨٦.\nلماذا حصرت العبادة لله تعالى؟\nإِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ ٥ ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ ٦\nفي قوله: (نعبد) بنون الاستتباع إشعار بأن الصلاة بنيت على الاجتماع. البقاعي: ١/١٧.\nلماذا كانت صيغة العبادة والاستعانة والدعاء في سورة الفاتحة بالجمع؟\nٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ ٦\nالحاجة إلى الهدى أعظم من الحاجة إلى النصر والرزق؛ بل لا نسبة بينهما؛ لأنه إذا هُدي كان من المتقين، ﴿وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجًا وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ﴾. ابن تيمية: ١/١١٦\nلماذا كانت الحاجة إلى الهدى أعظم من الحاجة إلى النصر والرزق؟\nٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ ٦\nعلى قدر ثبوت قدم العبد على هذا الصراط الذي نصبه الله لعباده في هذه الدار، يكون ثبوت قدمه على الصراط المنصوب على متن جهنم. وعلى قدر سيره على هذا الصراط يكون سيره على ذاك الصراط؛ فمنهم من يمر كالبرق، ومنهم من يمر كالطّرف... فلينظر العبد سيره على ذلك الصراط من سيره على هذا؛ حذو القُذَّة بالقُذَّة جزاءً وفاقًا؛ ﴿هَلۡ تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ﴾. ابن القيم: ١/٣٥\nما العلاقة بين التزام العبد الصراط المستقيم في الدنيا وسيره على الصراط في الآخرة؟"],[2,"§البقرة\nwords\nالمهَذَا القُرآنُ مُؤَلَّفٌ مِن هَذِهِ الحُرُوفِ، وَلاَ يَستَطِيعُونَ الإِتيَانَ بِمِثلِهِ.\nلِلمُتَّقِينَمَن جَعَلُوا بَينَهُم وَبَينَ عَذَابِ اللهِ وِقَايَةً بِفِعلِ الأَوَامِرِ وَتَركِ النَّوَاهِي.\ndeeds\nمبنى التقوى على مخالفة شرع الله لهوى نفسك اختبارًا لإيمانك، فحدد أمرًا في حياتك ترى أنك تقدِّم فيه هوى نفسك على شرع الله سبحانه وتراجع عنه مستغفرًا ربك.\nحاسب نفسك في أمر الصلاة، وتفقد اليوم جوانب التقصير فيها فكمله، وأقمه على الوجه المطلوب شرعًا.\nاختبر إيمانك باليوم الآخر ويقينك به بالإنفاق اليوم من مال الله الذي آتاك، موقنًا أن الله تعالى سيخلفه عليك في الدنيا والآخرة.\nguid\nمن أسباب حصول الهداية بالقرآن تقوى الله تعالى، فقدم دائمًا مراد الله على هوى نفسك.\nسعادتك بالفلاح، والفلاح لا يناله إلا من اتصف بهذه الصفات.\nمن أهم صفات المؤمنين: ثباتهم على إيمانهم في حال الغيب وحال الشهادة، ومراقبتهم لله على كل الأحوال.\nrefl\nالٓمٓ ١ ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ ٢\nإنَّما ذكرت هذه الحروف في أوائل السور التي ذكرت فيها بيانًا لإعجاز القرآن، وأن الخلق عاجزون عن معارضته بمثله، هذا مع أنه مركب من هذه الحروف المقطعة التي يتخاطبون بها... ولهذا كل سورة افتتحت بالحروف فلا بد أن يذكر فيها الانتصار للقرآن، وبيان إعجازه وعظمته، وهذا معلوم بالاستقراء. ابن كثير: ١/٣٦-٣٧.\nما سبب ارتباط الحروف المقطعة بذكر عظمة القرآن وإعجازه؟\nذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ ٢\nلم يقل: هدى للمصلحة الفلانية، ولا للشيء الفلاني؛ لإرادة العموم، وأنه هدى لجميع مصالح الدارين؛ فهو مرشد للعباد في المسائل الأصولية والفروعية، ومُبَيِّن للحق من الباطل، والصحيح من الضعيف، ومبين لهم كيف يسلكون الطرق النافعة لهم في دنياهم وأُخراهم. السعدي: ٤٠.\nكيف يستدل بهذه الآية على شمول هداية القرآن لمصالح الدارين؟\nٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ٣\nالإيمان بالغيب حظ القلب، وإقام الصلاة حظ البدن، ﴿وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾ حظ المال، وهذا ظاهر. القرطبي: ١/٧٤٦٥.\nجمعت الآية بين ثلاثة من مواضع التقوى، فما هي؟\nوَيُقِيمُونَ ٱلصَّلَوٰةَ\nلم يقل: يفعلون الصلاة، أو يأتون بالصلاة؛ لأنه لا يكفي فيها مجرد الإتيان بصورتها الظاهرة؛ فإقامة الصلاة: إقامتها ظاهرًا بإتمام أركانها وواجباتها وشروطها، وإقامتها باطنًا بإقامة روحها؛ وهو حضور القلب فيها، وتدبر ما يقوله ويفعله منها. السعدي: ٤١.\nلماذا عُبِّر عن فعل الصلاة بالإقامة؟\nوَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ\nوأتى بـ (من) الدالة على التبعيض؛ لينبههم أنه لم يرد منهم إلا جزءًا يسيرًا من أموالهم، غير ضار لهم، ولا مثقل، بل ينتفعون هم بإنفاقه، وينتفع به إخوانهم، وفي قوله: (رزقناهم) إشارة إلى أن هذه الأموال التي بين أيديكم، ليست حاصلة بقوتكم وملككم، وإنَّما هي رزق الله الذي خولكم، وأنعم به عليكم؛ فكما أنعم عليكم وفضلكم على كثير من عباده فاشكروه بإخراج بعض ما أنعم به عليكم. السعدي: ٤١.\nلماذا جيء بـ(من) الدالة على التبعيض؟\nٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ٣\nوجه ترتب الإنفاق على الإيمان بالغيب أن المدد غيب؛ لأن الإنسان لمَّا كان لا يطلع على جميع رزقه كان رزقه غيبًا، فإذا أيقن بالخلف جاد بالعطية، فمتى أمد بالأرزاق تمت خلافته، وعظم فيها سلطانه، وانفتح له باب إمداد برزق أعلى وأكمل من الأول. البقاعي: ١/٣٠.\nما وجه ترتب الإنفاق على الإيمان بالغيب؟\nوَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ\nواليقين أعلى درجات العلم؛ وهو الذي لا يمكن أن يدخله شك بوجه. ابن عطية: ١/٨٦.\nكلما عظم العلم بالآخرة عظم العمل لها؛ وضّح ذلك من الآية."],[3,"§البقرة\nwords\nخَتَمَ اللَّهُطَبَعَ اللهُ.\nغِشَاوَةٌغِطَاءٌ.\nمَرَضٌشَكٌّ، وَنِفَاقٌ.\nيَعمَهُونَيَتَحَيَّرُونَ، وَيَعمَونَ عَنِ الرُّشدِ.\ndeeds\nبين لمن حولك الخطورة والأكاذيب ممن يزعمون أنهم يدافعون عن حقوق المرأة وهم يريدون تحرير الوصول إليها.\nاستعذ بالله من النفاق.\nادعُ اليوم بأن يكفي الله الأمة شر المنافقين.\nguid\nالمعصية قد تكون سببًا لأن يختم الله على القلب فلا يستطيع الوصول إلى الحق.\nفَصَّلَ الله أحوال الكافرين في آيتين، وأحوال المنافقين بثلاث عشرة آية لأن خطر المنافقين أشد من خطر الكافرين؛ فالمنافقون ينخدع بهم عوام المسلمين.\nمن صفات المنافقين احتقار الصالحين والتقليل من شأنهم.\nrefl\nخَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ\nالذنوب إذا تتابعت على القلوب أغلقتها، وإذا أغلقتها أتاها حينئذ الختم من قبل الله تعالى والطبع؛ فلا يكون للإيمان إليها مسلك، ولا للكفر عنها مخلص، فذلك هو الختم والطبع الذي ذكره في قوله تعالى: ﴿خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ﴾. ابن كثير: ١/٤٥.\nكيف يحصل الختم على القلب؟\nخَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰٓ أَبۡصَٰرِهِمۡ غِشَٰوَةٞۖ\nثم ذكر الموانع المانعة لهم من الإيمان، فقال: ﴿خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ﴾ أي: طبع عليها بطابع لا يدخلها الإيمان، ولا ينفذ فيها، فلا يعون ما ينفعهم، ولا يسمعون ما يفيدهم، ﴿وَعَلَىٰٓ أَبۡصَٰرِهِمۡ غِشَٰوَةٌۖ﴾؛ أي: غشاء وغطاء وأكِنَّة تمنعها عن النظر الذي ينفعهم. وهذه طرق العلم والخير قد سدت عليهم؛ فلا مطمع فيهم، ولا خير يرجى عندهم، وإنَّما منعوا ذلك وسدت عنهم أبواب الإيمان بسبب كفرهم وجحودهم. السعدي: ٤٢.\nلماذا خُصَّت هذه الأعضاء بالختم والتغشية؟\nخَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰٓ أَبۡصَٰرِهِمۡ غِشَٰوَةٞۖ وَلَهُمۡ عَذَابٌ عَظِيمٞ ٧\nوفي تقديم السمع على البصر في مواقعه من القرآن دليل على أنه أفضل فائدة لصاحبه من البصر؛ فإن التقديم مؤذن بأهمية المقدم؛ وذلك لأن السمع آلة لتلقي المعارف التي بها كمال العقل، وهو وسيلة بلوغ دعوة الأنبياء إلى أفهام الأمم على وجه أكمل من بلوغها بواسطة البصر لو فقد السمع. ابن عاشور: ١/٢٥٨.\nالوسائل السمعية والوسائل البصرية أيهما أكثر أثرًا في البشر؟\nوَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَمَا هُم بِمُؤۡمِنِينَ ٨\nلما تقدم وصف المؤمنين في صدر السورة بأربع آيات، ثم عَرَّفَ حال الكافرين بهاتين الآيتين، شرع تعالى في بيان حال المنافقين الذين يظهرون الإيمان ويبطنون الكفر، ولما كان أمرهم يشتبه على كثير من الناس؛ أطنب في ذكرهم بصفات متعددة. ابن كثير: ١/٤٥.\nفي مقدمة سورة البقرة وصف الله أحوال المؤمنين بأربع آيات، والكافرين بآيتين، والمنافقين بثلاث عشرة آية، فلماذا؟\nوَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَمَا هُم بِمُؤۡمِنِينَ ٨\nنبه الله سبحانه على صفات المنافقين لئلَّا يغتر بظاهر أمرهم المؤمنون؛ فيقع لذلك فساد عريض من عدم الاحتراز منهم، ومن اعتقاد إيمانهم وهم كفار في نفس الأمر، وهذا من المحذورات الكبار. ابن كثير: ١/٤٦.\nما أهمية معرفة المسلمين لأحوال المنافقين؟\nفِي قُلُوبِهِم مَّرَضٞ فَزَادَهُمُ ٱللَّهُ مَرَضٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡذِبُونَ ١٠\n﴿فِي قُلُوبِهِم مَّرَضٌ﴾؛ أي: بسكونهم إلى الدنيا وحبهم لها، وغفلتهم عن الآخرة وإعراضهم عنها. وقوله: ﴿فَزَادَهُمُ ٱللَّهُ مَرَضًاۖ﴾؛ أي: وكلهم إلى أنفسهم، وجمع عليهم هموم الدنيا؛ فلم يتفرغوا من ذلك إلى اهتمام بالدين. ﴿وَلَهُمۡ عَذَابٌ أَلِيمُۢ﴾ بما يفنى عمَّا يبقى. وقال الجنيد: علل القلوب من اتباع الهوى، كما أن علل الجوارح من مرض البدن. القرطبي: ١/٣٠٠.\nما سبب حلول المرض بقلوب المنافقين؟\nأُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمۡ وَمَا كَانُواْ مُهۡتَدِينَ ١٦\nأي: رغبوا في الضلالة رغبة المشتري بالسلعة التي من رغبته فيها يبذل فيها الأثمان النفيسة، وهذا من أحسن الأمثلة؛ فإنه جعل الضلالة التي هي غاية الشر كالسلعة، وجعل الهدى الذي هو غاية الصلاح بمنزلة الثمن. السعدي: ٤٣.\nكيف تشترى الضلالة بالهدى؟"],[4,"§البقرة\nwords\nبُكمٌلاَ يَنطِقُونَ بِالحَقِّ.\nكَصَيِّبٍكَمَطَرٍ شَدِيدٍ.\nأَندَادًانُظَرَاءَ، وَأَمثَالًا.\nرَيبٍشَكٍّ.\ndeeds\nاقرأ اليوم مثلًا واحدًا من أمثلة القرآن، واجتهد في فهمه.\nنور القلب بيد الله سبحانه، فادعُ الله بقولك: \"اللهم اجعل في قلبي نورًا، وفي سمعي نورًا، وفي بصري نورًا\".\nتأمل هذه الآية، ثم استخرج منها فائدة وأرسلها في رسالة.\nguid\nعبادة الله -سبحانه وتعالى- هي الغاية من وجودك.\nالتأمل في مخلوقات الله سبحانه سببٌ لزيادة اليقين والإيمان في قلب العبد.\nمن الخلل العقلي والشرعي أن يكرمك الكريم، ثم تشرك معه غيره.\nrefl\nمَثَلُهُمۡ كَمَثَلِ ٱلَّذِي ٱسۡتَوۡقَدَ نَارٗا فَلَمَّآ أَضَآءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِي ظُلُمَٰتٖ لَّا يُبۡصِرُونَ ١٧\nفإن قيل: ما وجه تشبيه المنافقين بصاحب النار التي أضاءت ثم أظلمت؟ فالجواب من ثلاثة أوجه: أحدها: أن منفعتهم في الدنيا بدعوى الإيمان شبيه بالنور، وعذابهم في الآخرة شبيه بالظلمة بعده، والثاني: أن استخفاء كفرهم كالنور، وفضيحتهم كالظلمة، والثالث: أنّ ذلك فيمن آمن منهم ثم كفر، فإيمانه نور، وكفره بعده ظلمة، ويرجح هذا قوله: ﴿ذَٰلِكَ بِأَنَّهُمۡ ءَامَنُواْ ثُمَّ كَفَرُواْ﴾. ابن جزي: ١/٥٤.\nما وجه تشبيه المنافقين بصاحب النار التي أضاءت ثم أظلمت؟\nصُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَرۡجِعُونَ ١٨\nقال تعالى [عنهم]: (صم) أي: عن سماع الخير، (بكم) [أي]: عن النطق به، (عمي): عن رؤية الحق، ﴿فَهُمۡ لَا يَرۡجِعُونَ﴾: لأنهم تركوا الحق بعد أن عرفوه، فلا يرجعون إليه، بخلاف من ترك الحق عن جهل وضلال؛ فإنه لا يعقل، وهو أقرب رجوعًا منهم. السعدي: ٤٤.\nلماذا وصف الله -سبحانه وتعالى- المنافقين بأنهم لا يرجعون؟\nوَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٢٠\nإنَّما وصف الله تعالى نفسَه بالقدرة على كل شيء في هذا الموضع؛ لأنه حذر المنافقين بأسه وسطوته، وأخبرهم أنه بهم محيط، وعلى إذهاب أسماعهم وأبصارهم قدير. ابن كثير: ١/٥٥.\nما وجه ختم الآية بوصفه سبحانه بالقدرة على كل شيء؟\nيَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ ٢١\n﴿ٱعۡبُدُواْ رَبَّكُمُ﴾: يدخل فيه الإيمان به سبحانه، وتوحيده، وطاعته؛ فالأمر بالإيمان به لمن كان جاحدًا، والأمر بالتوحيد لمن كان مشركًا، والأمر بالطاعة لمن كان مؤمنًا. ابن جزي: ١/٥٦.\nبيّن أنواع الناس المدعوين في الآية.\nفَلَا تَجۡعَلُواْ لِلَّهِ أَندَادٗا وَأَنتُمۡ تَعۡلَمُونَ ٢٢\nهذه الآية من المحكم الذي اتفقت عليه الشرائع واجتمعت عليه الكتب، وهو عمود الخشوع، وعليه مدار الذل والخضوع. البقاعي: ١/٥٩.\nفي هذه الآية ضابط لعبادة الله، فما هو؟\nوَإِن كُنتُمۡ فِي رَيۡبٖ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ بِسُورَةٖ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ ٢٣ فَإِن لَّمۡ تَفۡعَلُواْ وَلَن تَفۡعَلُواْ\nأي: ولن تفعلوا ذلك أبدًا، وهذه أيضًا معجزة أخرى، وهو أنه أخبر خبرًا جازمًا قاطعًا مقدمًا غير خائف ولا مشفق أن هذا القرآن لا يعارض بمثله أبد الآبدين، ودهر الداهرين، وكذلك وقع الأمر لم يعارض من لدنه إلى زماننا هذا، ولا يمكن، وأنَّى يتأتى ذلك لأحد. ابن كثير: ١/٥٨.\nهذه الآية تدل على معجزة ظاهرة للقرآن الكريم، وضِّحها.\nوَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَٰفِرِينَ ٢٤\nوبدأ سبحانه بالناس؛ لأنهم الذين يدركون الآلام، أو لكونهم أكثر إيقادًا من الجماد؛ لما فيهم من الجلود واللحوم والشحوم، ولأن في ذلك مزيد التخويف. الألوسي: ١/١٩٩.\nلماذا قدم الناس على الحجارة في إيقاد النار؟"],[5,"§البقرة\nwords\nمُتَشَابِهًافِي اللَّونِ، وَالمَنظَرِ، لاَ فِي الطَّعمِ.\nاستَوَىقَصَدَ.\ndeeds\nاكتب ثلاث صفات تتمناها وقد ذكرها القرآن في الجنة.\nتذكَّر عهدًا قطعته على نفسك وأخرت الوفاء به، وبادر بذلك.\nقم اليوم بزيارة بعض أرحامك، أو إرسال هدية لهم، أو الاتصال والسؤال عنهم.\nguid\nالسكن، والرزق، والزوجة، والأمن من الموت؛ هذه أمنيات الإنسان، واكتمالها و دوامها لا يكون إلا في الجنة.\nالمؤمن إذا جاءه أمر عن الله تعالى قابله بالتسليم والامتثال، وأمَّا المنافق فيكثر الجدال بقصد إبطاله.\nالإيمان يكسب صاحبه فراسة يعرف بها الحق من الباطل.\nrefl\nوَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ\nوفيه استحباب بشارة المؤمنين وتنشيطهم على الأعمال بذكر جزائها ومثيراتها؛ فإنها بذلك تخف وتسهل. السعدي: ٤٧.\nما أهمية البشارة في حياة المؤمنين؟\nوَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ\nقال معاذ رضي الله عنه: العمل الصالح: الذي فيه أربعة أشياء: العلم، والنية، والصبر، والإخلاص. البغوي: ١/٢٧.\nكيف يكون العمل صالحًا؟\nوَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ\nأكمل محاسن الجنات جريان المياه في خلالها؛ وذلك شيء اجتمع البشر كلهم على أنه من أنفس المناظر. ابن عاشور: ١/٣٥٤.\nلماذا ذكرت الآية الكريمة جريان الأنهار من تحت الجنان؟\nوَلَهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ\nفلم يقل: \"مطهرة من العيب الفلاني\" ليشمل جميع أنواع التطهير؛ فهن مطهرات الأخلاق، مطهرات الخَلق، مطهرات اللسان، مطهرات الأبصار. السعدي: ٤٦.\nلماذا أطلق سبحانه وصف (مطهرات) للحور العين ولم يقيده ﴿وَلَهُمۡ فِيهَآ أَزۡوَٰجٌ مُّطَهَّرَةٌۖ وَهُمۡ فِيهَا خَٰلِدُونَ﴾؟\nوَهُمۡ فِيهَا خَٰلِدُونَ\nهذا هو تمام السعادة؛ فإنهم مع هذا النعيم في مقام أمين من الموت والانقطاع، فلا آخر له ولا انقضاء، بل في نعيم سرمدي أبدي على الدوام. ابن كثير: ١/٦١.\nلماذا ختم ذكر نعيم أهل الجنة بأنهم خالدون فيها؟\nوَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۘ يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ ٢٦\nذم لمن يضل به؛ فإنه فاسق، ليس أنه كان فاسقًا قبل ذلك؛ ولهذا تأولها سعد بن أبي وقاص في الخوارج، وسماهم (فاسقين) لأنهم ضلوا بالقرآن؛ فمن ضل بالقرآن فهو فاسق. ابن تيمية: ١/١٧٨.\nمن حرف معاني القرآن عن فهم سلف الأمة فهو فاسق؛ وضّح ذلك من الآية.\nيُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ ٢٦\nأي: ببركة اعتقادهم الخير، وتسليمهم له الأمر، يهديهم ربهم بإيمانهم؛ فيفهمهم المراد منه، ويشرح صدورهم لما فيه من المعارف؛ فيزيدهم به إيمانًا وطمأنينة وإيقانًا. والمهديون كثير في الواقع، قليل بالنسبة إلى الضالين. البقاعي: ١/٧٧.\nمَن الأولى بهداية الله سبحانه لفهم القرآن؟"],[6,"§البقرة\nwords\nوَيَسفِكُيُرِيقُ.\nوَنُقَدِّسُ لَكَنمجِّدُكَ، ونُطهِّرُ ذِكرَكَ عمَّا لا يَليقُ.\nرَغَدًاتَمَتُّعًا هَنِيئًا وَاسِعًا.\nفَأَزَلَّهُمَاأَوقَعَهُمَا فِي الخَطِيئَةِ.\ndeeds\nضع لنفسك جدولًا تتعلم فيه أهم المسائل التي تحتاجها.\nاقرأ قصة آدم -عليه الصلاة والسلام- من كتب التفسير وقصص الأنبياء، ثم استخرج ثلاث فوائد تهمك في حياتك.\nتذكر ما وقع منك أو من أسرتك من ذنب، ثم قل: \"ربنا ظلمنا أنفسنا، وإن لم تغفر لنا وترحمنا لنكونن من الخاسرين\".\nguid\nاعرف قدر أهل العلم، وتأدب معهم، فقد أمر الله تعالى الملائكة بالسجود لآدم بسبب علمه.\nالتسبيح من صفات الملائكة؛ فتشبَّه بهم.\nتواضع لله تعالى مهما بلغت من درجات في العلم، واطلب منه سبحانه الزيادة.\nrefl\nوَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ\nهذه الآية أصل في نصب إمام وخليفة يُسمع له ويُطاع؛ لتجتمع به الكلمة، وتنفذ به أحكام الخليفة، ولا خلاف في وجوب ذلك بين الأمة ولا بين الأئمة. القرطبي: ١/٣٩٥.\nبقاء الأمة بلا إمام ذنب يأثمون به لكثرة المفاسد؛ وضّح ذلك من الآية.\nأَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ\nفهذان السببان اللذان ذكرتهما الملائكة هما اللذان كتب الله على بني إسرائيل القتل بهما. ابن تيمية: ١/١٩٢.\nما السببان المؤديان إلى هلاك الأمم إذا انتشرا فيها؟\nأَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ\nوقول الملائكة هذا ليس على وجه الاعتراض على الله، ولا على وجه الحسد لبني آدم... وإنَّما هو سؤال استعلام واستكشاف عن الحكمة في ذلك. ابن كثير: ١/٦٧.\nلامَ الله سبحانه إبليس على سؤاله، ولم يعاتب الملائكة على سؤالهم؛ فلماذا؟\nقَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ\n﴿أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا﴾ بالمعاصي ﴿وَيَسۡفِكُ ٱلدِّمَآءَ﴾؛ وهذا تخصيص بعد تعميم؛ لبيان شدة مفسدة القتل. السعدي: ٤٨.\nلماذا خُصَّ سفك الدماء بالذكر مع أنه داخل في الإفساد؟\nقَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ٣٢\nالواجب على من سُئل عن علم أن يقول إن لم يعلم: الله أعلم، ولا أدري؛ اقتداء بالملائكة، والأنبياء، والفضلاء من العلماء، لكن أخبر الصادق أن بموت العلماء يُقبض العلم، فيبقى ناس جهال يُستفتَون؛ فيُفتون برأيهم؛ فيضلون، ويُضلون. القرطبي: ١/٤٢٥.\nماذا نفيد من قول الملائكة: ﴿سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ﴾؟\nوَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ ٣٥\nالنهي عن القرب يقتضي النهي عن الأكل بطريق الأولى، وإنَّما نهى عن القرب؛ سدًّا للذريعة، فهذا أصل في سدّ الذرائع. ابن جزي: ١/٦٢.\nما الطريقة المثالية في الحذر من المعاصي؟\nفَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ ٣٧\nسبقت رحمته غضبه؛ فيرحم عبده في عين غضبه، كما جعل هبوط آدم سبب ارتفاعه، وبعده سبب قربه، فسبحانه من تواب ما أكرمه، ومن رحيم ما أعظمه. الألوسي: ١/٢٣٨.\nبعد قصة آدم -عليه السلام- لا نيأس من رحمة الله سبحانه؛ وضّح ذلك."],[7,"§البقرة\nwords\nفَارهَبُونِخَافُونِ.\nوَلاَ تَلبِسُوالاَ تَخلِطُوا.\nيَظُنُّونَيُوقِنُونَ.\nعَدلٌفِديَةٌ.\ndeeds\nذكِّراليوم من حولك بنعم الله عليكم ووجوب شكرها حتى تدوم.\nاحرص اليوم على التبكير لصلاة الجماعة، وذكر غيرك بفضلها، وأكثر من تعظيم الله في الركوع.\nحدد فعلًا خاطئًا تغلبك نفسك عليه أحيانًا، وحذر منه غيرك، لعله يثير فيك الحياء من الله؛ فتتركه أبدًا.\nguid\nاتِّبَاعُ تعاليم الدين يحصل به الأمن وانشراح الصدر، ويبعد الخوف والضيق في الدنيا والآخرة.\nلا تجعل هدفك من حفظ كتاب الله وفهمه تحصيلَ شيءٍ من متاع الحياة الدنيا.\nبالصبر والصلاة تتيسر الحياة.\nrefl\nيَٰبَنِيٓ إِسۡرَٰٓءِيلَ\nمُهَيِّجًا لهم بذكر أبيهم إسرائيل، وهو نبي الله يعقوب -عليه السلام-، وتقديره: يا بني العبد الصالح المطيع لله: كونوا مثل أبيكم في متابعة الحق، كما تقول: يا ابن الكريم: افعل كذا، يا ابن الشجاع: بارز الأبطال، يا ابن العالم: اطلب العلم، ونحو ذلك. ابن كثير: ١/٧٩.\nلماذا نادى اليهودَ ناسبًا إياهم إلى أبيهم إسرائيل (يعقوب) -عليه السلام-؟\nوَءَامِنُواْ بِمَآ أَنزَلۡتُ مُصَدِّقٗا لِّمَا مَعَكُمۡ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۢ بِهِۦۖ\nتصديق القرآن للتوراة وغيرها، وتصديق محمد -صلى الله عليه وسلم- للأنبياء والمتقدمين له ثلاث معان: أحدها: أنهم أخبروا به؛ ثم ظهر كما قالوا؛ فتبين صدقهم في الإخبار به، والآخر: أنه -صلى الله عليه وسلم- أخبر أنهم أنبياء، وأنزل عليهم الكتب، فهو مصدق لهم؛ أي: شاهد بصدقهم، والثالث: أنه وافقهم فيما في كتبهم من التوحيد وذكر الدار الآخرة وغير ذلك من عقائد الشرائع؛ فهو مصدق لهم لاتفاقهم في الإيمان بذلك. ابن جزي: ١/٦٤.\nكيف يكون القرآن مصدقًا للكتب السابقة؟\nوَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗا وَإِيَّٰيَ فَٱتَّقُونِ ٤١\nوهذه الآية وإن كانت خاصة ببني إسرائيل فهي تتناول من فعل فعلهم؛ فمن أخذ رشوة على تغيير حق أو إبطاله، أو امتنع من تعليم ما وجب عليه، أو أداء ما علمه -وقد تَعَيَّن عليه- حتى يأخذ عليه أجرًا؛ فقد دخل في مقتضى الآية. القرطبي: ٢/١١.\nكيف يشتري الإنسان بآيات الله ثمنًا قليلًا؟\nوَلَا تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُواْ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ ٤٢\nاستُدِل بالآية على أن العالم بالحق يجب عليه إظهاره، ويحرم عليه كتمانه بالشروط المعروفة لدى العلماء. الألوسي: ١/٢٤٧.\nبماذا استُدِل بالآية؟\nأَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ\nوليس المراد: ذمهم على أمرهم بالبر مع تركهم له، بل على تركهم له؛ فإن الأمر بالمعروف معروف، وهو واجب على العالم، ولكن الواجب والأولى بالعالم أن يفعله مع أمرهم به ولا يتخلف عنهم... فكُلٌّ من الأمر بالمعروف وفعله واجب، لا يسقط أحدهما بترك الآخر. ابن كثير: ١/٨٢.\nصاحب المعصية إذا رأى غيره يفعلها؛ هل يسكت عنه؟\nوَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ ٤٥\nأخبر الله- جل ثناؤه- أن الصلاة كبيرة إلا على من هذه صفته. الطبري: ١/٢٢.\nما الصفة التي تحبب الصلاة للمؤمن، وتشوقه إليها؟\nوَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ ٤٥\nوإنَّما لم تثقل عليهم؛ لأنهم عارفون بما يحصل لهم فيها، متوقعون ما ادخر من ثوابها؛ فتهون عليهم، ولذلك قيل: \"من عرف ما يطلب هان عليه ما يبذل، ومن أيقن بالخلف جاد بالعطية\". الألوسي: ١/٢٤٩.\nلماذا لم تثقل الصلاة على الخاشعين؟"],[8,"§البقرة\nwords\nفَرَقنَافَصَلنَا.\nبَارِئِكُمخَالِقِكُم.\nالغَمَامَالسَّحَابَ.\nالمَنَّشيءٌ يُشبِهُ الصَّمغَ كَالعَسَلِ.\ndeeds\nاكتب قائمة بالنوازل والمخاطر التي حفظ الله منها المجتمع وكفاهم إياها، ثم أرسلها برسالة تذكير بالشكر؛ فإن الله يحب الشاكرين.\nذكّر غافلًا بأن شرط توبة عصاة بني إسرائيل كان أن يقتلوا أنفسهم، وأمَّا عصاة أمة محمد -صلى الله عليه وسلم- فخفف الله عنهم بالاقتصار على طلب الاستغفار والتوبة الصادقة.\nراجع قائمة طعامك، وابتعد عن المشتبه به؛ فإن البدائل الحلال كثيرة، واقتصر على الطيب من الرزق.\nguid\nكلما اشتد ظلم طاغية اقترب زوال ملكه.\nلا تيأس من كثرة معاصيك؛ فإن كان الله سبحانه يغفر الشرك -وهو أكبر المعاصي- إذا تاب العبد منه، فما عليك إلا أن تقبل على الله سبحانه بالتوبة الصادقة.\nمن رحمة الله بالعباد أنه يمهلهم ولا يعاجلهم العقوبة لعلهم يتوبون إليه ويستغفرونه؛ فيغفر لهم.\nrefl\nوَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ ٥٠\nأغرقناهم وأنتم تنظرون؛ ليكون ذلك أشفى لصدوركم، وأبلغ في إهانة عدوكم. ابن كثير: ١/٨٧.\nتوعد فرعون المؤمنين بالصلب؛ ليتشفى بهم، فعامله الله بمثل ما توَعَّدَ به، بيِّن ذلك.\nوَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ أَرۡبَعِينَ لَيۡلَةٗ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ ٥١\nوخصَّ الليل بالذكر؛ إشارة إلى أن ألذ المناجاة فيه. البقاعي: ١/١٣٣.\nلماذا خصَّ الليل دون النهار بالمناجاة؟\nوَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ\nالفعل الذي فعلوه فظلموا به أنفسهم هو ما أخبر الله عنهم من ارتدادهم باتخاذهم العجل ربًّا بعد فراق موسى إياهم. الطبري: ٢/٧٢.\nغياب العلماء والصالحين عن المجتمع مظنة انحرافه؛ وضّح ذلك.\nوَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ\nجعلتم أنفسكم متذللة لمن لا يملك لها شيئًا ولمن هي أشرف منه، فهذا هو أسوأ الظلم؛ فإن المرء لا يصلح أن يتذلل ويتعبد لمثله، فكيف لمن دونه من حيوان! فكيف بما يشبه بالحيوان من جماد الذهب الذي هو من المعادن. البقاعي: ١/١٣٤.\nأسوأ الجهل الجهل بالربوبية؛ وضّح ذلك.\nوَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ\nلما ذكر تعالى ما دفعه عنهم من النقم شرع يُذَكِّرُهم أيضًا بما أسبغ عليهم من النعم فقال: ﴿وَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ﴾. ابن كثير: ١/٩٠.\nما علاقة هذه الآية بما قبلها من الآيات؟\nوَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ٥٧\nفكان ينزل عليهم من المن والسلوى ما يكفيهم ويُقِيتُهم. ﴿كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ﴾ أي: رزقًا لا يحصل نظيره لأهل المدن المترفهين. فلم يشكروا هذه النعمة، واستمروا على قساوة القلوب وكثرة الذنوب. السعدي: ٤٩.\nما سبب توالي العقوبات وشدتها على بني إسرائيل؟\nوَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ٥٧\nوالجمع بين صيغتي الماضي والمستقبل للدلالة على تماديهم في الظلم واستمرارهم عليه. الألوسي: ١/٢٦٤.\nلماذا عبر عن ظلم بني إسرائيل بالفعل الماضي والمستقبل؟"],[9,"§البقرة\nwords\nوَقُولُوا حِطَّةٌأَي: قُولُوا احطُط، وَضَع عَنَّا ذُنُوبَنَا.\nرِجزًاعَذَابًا.\nوَلاَ تَعثَوالاَ تَسعَوا.\nوَبَاءُوارَجَعُوا.\ndeeds\nاحـرص اليـوم على السنن الـرواتـب، واستمر في المحافظة عليـها.\nاقرأ الألفاظ والأذكار الصحيحة الواردة في الصلاة من أحد كتب صفة الصلاة الموثقة بالأدلة الصحيحة، وصحح ما عندك فيها من أخطاء.\nذكّر أسرتك بنعمة يستقلونها بينما تفتقدها كثير من الأسر.\nguid\nاحذر أن يُفتح لك باب رحمة وعمل صالح فتضيعه بتفريط منك.\nلا تستقل رزق الله لك فيبدلك الله ما ظاهره الخير وهو شر لك.\nمن عاقبة المعصية: الذل، والفقر، وغضب الله.\nrefl\nوَإِذۡ قُلۡنَا ٱدۡخُلُواْ هَٰذِهِ ٱلۡقَرۡيَةَ فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَدٗا وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُولُواْ حِطَّةٞ\nوحاصل الأمر: أنهم أمِروا أن يخضعوا لله تعالى عند الفتح بالفعل والقول، وأن يعترفوا بذنوبهم، ويستغفروا منها، والشكر على النعمة عندها.... ولهذا كان -عليه الصلاة والسلام- يظهر عليه الخضوع جدًّا عند النصر، كما روي أنه كان يوم الفتح -فتح مكة- داخلًا إليها من الثنية العليا، وإنه لخاضع لربه، حتى إن عثنونه ليمس مورك رحله شكرًا لله على ذلك، ثم لمَّا دخل البلد اغتسل وصلى ثماني ركعات. ابن كثير: ١/٩٤.\nما الذي ينبغي على المسلمين أن يفعلوه حالة النصر والفوز والظفر؟\nقَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرٗا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِۗ\nفيه تهديد لهذه الأمة بما غلب على أهل الدنيا منهم من مثل أحوالهم باستبدال الأدنى في المعنى من الحرام والمتشابه بالأعلى من الطيب. البقاعي: ١/١٤٩.\nماذا تفيد هذه الأمة مما حصل لليهود، وما يحصل لهم؟\nوَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ\nولما كان الذي جرى منهم فيه أكبر دليل على قلة صبرهم، واحتقارهم لأوامر الله ونعمه؛ جازاهم من جنس عملهم، فقال: ﴿وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ﴾ التي تشاهد على ظاهر أبدانهم، (والمسكنة) بقلوبهم. السعدي: ٥٣.\nلماذا كانت الذلة والمسكنة عقوبة مناسبة لمعاصي بني إسرائيل؟\nوَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ\nومعنى لزوم الذلة والمسكنة لليهود أنهم فقدوا البأس والشجاعة، وبدا عليهم سيما الفقر والحاجة مع وفرة ما أنعم الله عليهم؛ فإنهم لمَّا سئموها صارت لديهم كالعدم، ولذلك صار الحرص لهم سجية باقية في أعقابهم. ابن عاشور: ١/٥٢٨.\nالحرص والطمع صفة يهودية، كيف دلت الآية الكريمة على اتصاف اليهود بها؟\nوَيَقۡتُلُونَ ٱلنَّبِيِّۧنَ بِغَيۡرِ ٱلۡحَقِّۗ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ ٦١\n﴿ذَٰلِكَ بِمَا عَصَواْ﴾ بأن ارتكبوا معاصي الله، ﴿وَّكَانُواْ يَعۡتَدُونَ﴾ على عباد الله؛ فإن المعاصي يجر بعضها بعضًا، فالغفلة ينشأ عنها الذنب الصغير، ثم ينشأ عنه الذنب الكبير، ثم ينشأ عنها أنواع البدع والكفر وغير ذلك، فنسأل الله العافية من كل بلاء. السعدي: ٥٣.\nإذا استسلم الغافل للصغائر؛ أوقعته بالكبائر، ثم الكفر؛ وضّح ذلك من الآية.\nذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّۧنَ بِغَيۡرِ ٱلۡحَقِّۗ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ ٦١\nإدمان المعاصي يفضي إلى التغلغل فيها، والتنقل من أصغرها إلى أكبرها. ابن عاشور: ١/٥٣٠.\nانتقل بنو إسرائيل من المعاصي الصغيرة إلى الكفر وقتل الأنبياء؛ ماذا يفيد هذا ؟\nذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّۧنَ بِغَيۡرِ ٱلۡحَقِّۗ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ ٦١\nوالمعنى: أن الذي حملهم على الكفر بآيات الله تعالى وقتلهم الأنبياء إنَّما هو تقدم عصيانهم، واعتدائهم، ومجاوزتهم الحدود، والذنب يجر الذنب. الألوسي: ١/٢٧٧.\nما الذي حمل اليهود على الكفر بآيات الله تعالى وقتلهم الأنبياء؟"],[10,"§البقرة\nwords\nوَالصَّابِئِينَقَومٌ بَاقُونَ عَلَى فِطرَتِهِم، وَلاَ دِينَ لَهُم يَتَّبِعُونَهُ.\nفَارِضٌمُسِنَّةٌ هَرِمَةٌ.\nبِكرٌصَغِيرَةٌ فَتِيَّةٌ.\nعَوَانٌمُتَوَسِّطَةٌ بَينَ المُسِنَّةِ وَالصَّغِيرَةِ.\nفَاقِعٌشَدِيدَةُ الصُّفرَةِ.\ndeeds\nاخرج اليوم إلى أعمالك الدينية والدنيوية مبكرًا، وحاول أن تكون أكثر جدية، وأعلى همةً، ثم تأمل الفرق في النتائج.\nأرسل رسالة لمن حولك تذكر فيها أن المعصية بتحايل أكثر جلبًا لسخط الله من المعصية بلا تحايل.\nأرسل رسالة تذكر المجتمع فيها بعلم الله سبحانه بالفرق بين التقوى الكاذبة والتقوى الصادقة.\nguid\nعلى المسلم أن يتمسك بدينه بقوة، وأن لا يكون سريع التنازل عن شيءٍ منه أمام الأحداث والمصائب.\nما يحصل لغيرك من عقوبة فيه عبرةٌ وعظةٌ لك.\nاذكر فضل الله ورحمته عليك بهذا الإسلام، واشكره على ذلك؛ فلولاه لكنت من الخاسرين في الدنيا والآخرة.\nrefl\nإِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِٔينَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ٦٢\nوهذه طريقة القرآن: إذا وقع في بعض النفوس عند سياق الآيات بعض الأوهام، فلا بد أن تجد ما يزيل ذلك الوهم؛ لأنه تنزيل مَن يعلم الأشياء قبل وجودها، ومَن رحمتُه وسعت كل شيء، وذلك -والله أعلم- أنه لمَّا ذكر بني إسرائيل وذمَّهم، وذكر معاصيهم وقبائحهم، ربما وقع في بعض النفوس أنهم كلهم يشملهم الذم، فأراد الباري تعالى أن يبين من لم يلحقه الذم منهم بوصفه. ولما كان أيضًا ذكر بني إسرائيل خاصة يوهم الاختصاص بهم؛ ذكر تعالى حكمًا عامًا يشمل الطوائف كلها؛ ليتضح الحق، ويزول التوهم والإشكال. السعدي: ٥٤.\nلماذا وردت هذه الآية بعد ذكر قبائح بني إسرائيل؟\nوَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ\nالمراد بالقوة الجد والاجتهاد وعدم التكاسل والتغافل. الألوسي: ١/٢٨١.\nإلى ماذا يشير أخذ ما أنزل الله بقوة في الآية؟\nوَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِٔينَ ٦٥\nوإنَّما جعل الاعتداء فيه مع أن الحفر في يوم الجمعة لأن أثره الذي ترتب عليه العصيان -وهو دخول الحيتان للحياض- يقع في يوم السبت.ابن عاشور: ١/٥٤٤.\nلماذا جعل اعتداء اليهود في السبت مع أنهم حفروا يوم الجمعة؟\nفَجَعَلۡنَٰهَا نَكَٰلٗا لِّمَا بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ ٦٦\nولكنها لا تكون موعظة نافعة إلا للمتقين، وأمَّا من عداهم فلا ينتفعون بالآيات.السعدي:٥٤.\nلماذا خُصَّت الموعظة بالمتقين؟\nوَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةٗۖ\nقال الماوردي: \"وإنَّما أُمروا -والله أعلم- بذبح بقرة دون غيرها؛ لأنها من جنس ما عبدوه من العجل؛ ليهون عندهم ما كان يرونه من تعظيمه، وليعلم بإجابتهم ما كان في نفوسهم من عبادته\". القرطبي: ٢/١٧٧\nما الحكمة في أمر الله تعالى لهم بذبح بقرة؟\nقَالُوٓاْ أَتَتَّخِذُنَا هُزُوٗاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ ٦٧\nلأنه لا يليق بالعقلاء الأفاضل؛ فإنه أخص من المزح لأن في الهزؤ مزحًا مع استخفاف واحتقار للممزوح معه، على أن المزح لا يليق في المجامع العامة والخطابة، على أنه لا يليق بمقام الرسول؛ ولذا تبرأ منه موسى. ابن عاشور: ١/٥٤٨.\nلماذا رد موسى على سؤال قومه بقوله: ﴿أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ﴾؟\nقَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا فَارِضٞ وَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ ٦٨ قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ صَفۡرَآءُ فَاقِعٞ لَّوۡنُهَا تَسُرُّ ٱلنَّٰظِرِينَ ٦٩\nفلو لم يعترضوا لأجزأت عنهم أدنى بقرة، ولكنهم شدّدوا فشدَّد عليهم، حتى انتهوا إلى البقرة التي أمروا بذبحها فوجدوها عند رجل ليس له بقرة غيرها، فقال: والله لا أنقصها من ملء جلدها ذهبًا، فأخذوها فذبحوها.ابن كثير: ١/١٠٣.\nما خطورة التعنت والتشدد في الدين؟"],[11,"§البقرة\nwords\nلاَ ذَلُولٌغَيرُ مُذَلَّلَةٍ لِلعَمَلِ فِي الحِرَاثَةِ.\nمُسَلَّمَةٌخَالِيَةٌ مِنَ العُيُوبِ.\nلاَ شِيَةَلَيسَ فِيهَا عَلاَمَةٌ مِن لَونٍ يُخَالِفُ لَونَهَا.\nفَادَّارَأتُمتَنَازَعتُم، وَتَدَافَعتُم تُهَمَةَ القَتلِ.\ndeeds\n\"ميزان القلب خلواته\" انفرد بنفسك منشغلًا بعبادة من العبادات؛ فالله تعالى يعلم ما تخفي وما تظهر.\nاحذر طول العهد بمرققات القلوب، واعمل اليوم عملًا يرقق قلبك؛ كتغسيل ميت، أو دفنه، أو زيارة لقسم الطوارئ، أو لأحد العُبَّاد أو الزهَّاد.\nأرسل رسالة أو مقالًا عن بعض نماذج النفاق المعاصرة.\nguid\nالاستجابة للأوامر الشرعية بعد كثرة طرحٍ الأسئلة المتكلفة نوع من التعنُّت أو التقوى الكاذبة.\nالله قادر على إظهارِ ما تخفيه من الذنوب؛ فلا تجعله أهون الناظرين إليك.\nالمعاصي هي سبب قسوة القلب.\nrefl\nوَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ\nلولا أن القوم استثنوا فقالوا: ﴿وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ﴾؛ لما هُدوا إليها أبدًا. ابن كثير: ١/١٠٤.\nما الفائدة التي عادت على قوم موسى من الاستثناء؟\nقَالُواْ ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ\nوهذا من جهلهم، وإلا فقد جاءهم بالحق أول مرة، فلو أنهم اعترضوا أيَّ بقرة لحصل المقصود، لكنهم شددوا بكثرة الأسئلة؛ فشدد الله عليهم. السعدي: ٥٥.\nعلى ماذا يدل قول قوم موسى ﴿ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ﴾؟\nفَذَبَحُوهَا وَمَا كَادُواْ يَفۡعَلُونَ ٧١\nلعصيانهم وكثرة سؤالهم، أو لغلاء البقرة -فقد جاء أنها كانت ليتيم، وأنهم اشتروها بوزنها ذهبًا- أو لقلة وجود تلك الصفة؛ فقد روي أنهم لو ذبحوا أدنى بقرة أجزأت عنهم، ولكنهم شدّدوا فشُدِّد عليهم. ابن جزي: ١/٧٠.\nالتقوى الكاذبة تجلب للعبد العنت والمشقة، بعكس التقوى الصادقة، بيِّن ذلك من الآية.\nثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةٗۚ\nثم وصف قسوتها بأنها كالحجارة، التي هي أشد قسوة من الحديد؛ لأن الحديد والرصاص إذا أُذِيب في النار ذاب، بخلاف الأحجار. السعدي: ٥٥.\nلماذا شُبِّهَت قلوبهم القاسية بالحجارة، ولم تشبه بالحديد مثلًا؟\nثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةٗۚ\nوقوة القلب المحمودة غير قسوته المذمومة، فإنه ينبغي أن يكون قويًّا من غير عنف، ولينًا من غير ضعف. ابن تيمية: ١/٢٤٣.\nما الفرق بين قوة القلب وقسوته؟\nوَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا يَتَفَجَّرُ مِنۡهُ ٱلۡأَنۡهَٰرُۚ وَإِنَّ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ ٱلۡمَآءُۚ وَإِنَّ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ ٱلۡمَآءُۚ وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشْيَةِ ٱللَّهِ ٧٤\nإن من الحجارة ما هو أنفع من قلوبكم؛ لخروج الماء منها وترديها، قال مجاهد: ما تردى حجر من رأس جبل، ولا تفجر نهر من حجر، ولا خرج منه ماء إلا من خشية الله؛ نزل بذلك القرآن. القرطبي: ٢/٢٠٨.\nبيّن من خلال الآية كيف تكون بعض الحجارة أنفع من القلوب القاسية.\nأَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقٞ مِّنۡهُمۡ يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ يَعۡلَمُونَ ٧٥\n﴿مِنۢ بَعۡدِ مَا عَقَلُوهُ﴾؛ أي: عرفوه وعلموه. وهذا توبيخ لهم؛ أي: إن هؤلاء اليهود قد سلفت لآبائهم أفاعيل سوء وعناد، فهؤلاء على ذلك السَّنن، فكيف تطمعون في إيمانهم؟! ودل هذا الكلام أيضًا على أن العالِم بالحق المعاند فيه بعيد من الرشد؛ لأنه علم الوعد والوعيد ولم ينهه ذلك عن عناده. القرطبي: ٢/٢١٣.\nأيهما أقرب للهداية: الجاهل أم العالم المعاند؟"],[12,"§البقرة\nwords\nأُمِيُّونَيَجهَلُونَ القِرَاءَةَ وَالكِتَابَةَ.\nأَمَانِيَّتِلاَوَةً أَو أَكَاذِيبَ تَلَقَّوهَا عَن أَحبَارِهِم.\nفَوَيلٌهَلاَكٌ، وَدَمَارٌ.\nمِيثَاقَالعَهدَ المُؤَكَّدَ.\nحُسنًاكَلاَمًا طَيِّبًا.\ndeeds\nأرسل رسالة عن أهمية إصلاح السريرة من خلال هذه الآية الكريمة.\nابدأ اليوم ببرنامج في فهم آيات القرآن من خلال قراءة أحد التفاسير الميسرة؛ لتكون ممن فهم كلام الله تعالى.\nاختر إحدى هذه العبادات، ونفِّذها اليوم حتى تكون عاملًا بالقرآن، وانظر كيف تجد قلبك بعد ذلك.\nguid\nتذكر أن الله يعلم ما تسر وما تعلن؛ فلا يرينّك في سرك وعلانيتك إلا على خير.\nلا تتهاون بعذابٍ؛ فذلك يفضي إلى القسوة ومزيد من المعاصي.\nقرن الله حق الوالدين بحقه؛ فلا تتساهل في حق والديك.\nrefl\nوَمِنۡهُمۡ أُمِّيُّونَ لَا يَعۡلَمُونَ ٱلۡكِتَٰبَ إِلَّآ أَمَانِيَّ وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ ٧٨\n﴿إِلَّآ أَمَانِيَّ﴾: تلاوة بغير فهم. ابن جزي: ١/٧٢.\nكيف تفهم من هذه الآية الذم لمن يقرأ القرآن بغير فهم؟\nوَمِنۡهُمۡ أُمِّيُّونَ لَا يَعۡلَمُونَ ٱلۡكِتَٰبَ إِلَّآ أَمَانِيَّ وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ ٧٨\nهذه صفة من لا يفقه كلام الله، ويعمل به، وإنَّما يقتصر على مجرد تلاوته، كما قال الحسن البصري: نزل القرآن ليُعمل به؛ فاتَّخذوا تلاوته عملًا. ابن تيمية: ١/٢٤٧.\nترك تدبر القرآن الكريم والعمل به مذموم في القرآن الكريم؛ بين ذلك.\nفَوَيۡلٞ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ\nوإنَّما فعلوا ذلك مع علمهم ﴿لِيَشۡتَرُواْ بِهِۦ ثَمَنًا قَلِيلًاۖ﴾، والدنيا كلها من أولها إلى آخرها ثمن قليل، فجعلوا باطلهم شَرَكًا يصطادون به ما في أيدي الناس، فظلموهم من وجهين: من جهة تلبيس دينهم عليهم، ومن جهة أخذ أموالهم بغير حق، بل بأبطل الباطل، وذلك أعظم ممن يأخذها غصبًا وسرقةً ونحوهما. السعدي: ٥٦.\nمن حرف نص الكتاب أو معناه فهو ظالم من جهتين. بيِّنهما.\nوَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا\nوأمرناهم بالوالدين إحسانًا. وقرن الله -عز وجل- في هذه الآية حق الوالدين بالتوحيد لأن النشأة الأولى من عند الله، والنشء الثاني -وهو التربية- من جهة الوالدين، ولهذا قرن تعالى الشكر لهما بشكره. القرطبي: ٢/٢٢٩.\nلماذا قرن الله سبحانه بين حقه وحق الوالدين؟\nوَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ لِلنَّاسِ حُسۡنٗا\nوناسب أن يأمرهم بأن يقولوا للناس حسنًا بعد ما أمرهم بالإحسان إليهم بالفعل؛ فجمع بين طرفي الإحسان الفعلي والقولي.ابن كثير: ١/١١٥.\nلماذا ذكر القول الحسن بعد أن ذكر الإحسان؟\nوَقُولُواْ لِلنَّاسِ حُسۡنٗا\nوجعل الإحسان لسائر الناس بالقول؛ لأنه القدر الذي يمكن معاملة جميع الناس به، وذلك أن أصل القول أن يكون عن اعتقاد، فهم إذا قالوا للناس حُسنًا فقد أضمروا لهم خيرًا. ابن عاشور: ١/٥٨٣.\nلماذا جعل الله تعالى الإحسان لسائر الناس بالقول؟\nوَقُولُواْ لِلنَّاسِ حُسۡنٗا\nهو اللين في القول، والمعاشرة بحسن الخلق. البغوي: ١/٧٢.\nبيِّن فضل الإحسان في القول ومكانته في الدين."],[13,"§البقرة\nwords\nتُفَادُوهُمتَسعَوا فِي تَحرِيرِهِم مِنَ الأَسرِ.\nخِزيٌذُلٌّ، وَفَضِيحَةٌ.\nوَقَفَّينَاأَتبَعنَا.\nغُلفٌمُغَطَّاةٌ.\ndeeds\nاسع في فك أسير أو سجين بشفاعة، أو بتقديم مال، أو بدعوة صالحة في جوف الليل، أو في ساعة إجابة.\nاطلب النصيحة من أحد زملائك، واقبلها طالما أنها حق، ولا تردها لأنها لا توافق هواك.\nقل: \"رضيت بالله ربا، وبمحمد -صلى الله عليه وسلم- رسولًا، وبالإسلام دينًا\".\nguid\nتأمل كيف سمى الله تعالى قتل بعضهم بعضًا قتلًا لأنفسهم؛ لأن المؤمن مع أخيه كالنفس الواحدة؛ يحزنه ما أحزنه، ويفرحه ما أفرحه.\nالإيمان بالله سبحانه هو الرضى بالدين كاملًا، أما انتقاء بعض الأحكام ورد البعض الآخر فنوع من النفاق والعياذ بالله.\nاليهود غير مؤتمنين على التوراة التي بين أيديهم؛ فكيف يؤتمنون على غيرها من المعاهدات والمواثيق.\nrefl\nوَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ\nوردت الآثار عن النبي -صلى الله عليه وسلم- أنه فك الأُسارى، وأمر بفكهم، وجرى بذلك عمل المسلمين، وانعقد به الإجماع، ويجب فك الأسارى من بيت المال، فإن لم يكن فهو فرض على كافة المسلمين، ومن قام به منهم أسقط الفرض عن الباقين. القرطبي: ٢/٢٤٢.\nما واجبنا تجاه أسارى المسلمين في العالم؟\nأَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضٖۚ\nوفيها أكبر دليل على أن الإيمان يقتضي فعل الأوامر واجتناب النواهي، وأن المأمورات من الإيمان. السعدي: ٥٨.\nكيف ترد بهذه الآية على من يزعم الإيمان وهو لا يعمل؟\nأُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۖ\nأخبر تعالى عن السبب الذي أوجب لهم الكفر ببعض الكتاب والإيمان ببعضه، فقال: (أولئك الذين اشتروا الحياة الدنيا بالآخرة). السعدي: ٥٨.\nما السبب الذي جعل بعض الناس يؤمنون ببعض الكتاب، ويكفرون ببعض؟\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَقَفَّيۡنَا مِنۢ بَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ\nالتأييد بروح القدس لمن ينصر الرسل عام في كل من نصرهم على من خالفهم من المشركين وأهل الكتاب. ابن تيمية: ١/٢٦٨.\nمن الذي ينصره الله تعالى بروح القدس؟\nأَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُكُمُ ٱسۡتَكۡبَرۡتُمۡ\nوسُمي الهوى هوىً؛ لأنه يهوي بصاحبه إلى النار، ولذلك لا يُستعمل في الغالب إلا فيما ليس بحق، وفيما لا خير فيه. القرطبي: ٢/٢٤٥.\nإلى أين يجر الهوى صاحبه؟\nوَقَالُواْ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلٗا مَّا يُؤۡمِنُونَ ٨٨\nقلوبنا مغشاة بأغشية خلقية، مانعة عن نفوذ ما جئت به؛ فيها إقناط النبي -صلى الله عليه وسلم- عن الإجابة، وقطع طمعه عنهم بالكلية؛ فأقصاهم الله تعالى عن رحمته. الألوسي: ١/٣١٨.\nماذا قصد اليهود من قولهم ﴿قُلُوبُنَا غُلۡفُۢۚ﴾ وبماذا عوقبوا؟\nوَقَالُواْ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلٗا مَّا يُؤۡمِنُونَ ٨٨\nأضرب الله سبحانه عنه بقوله: (بل)؛ أي: ليس الأمر كما قالوا من أن هناك غلفًا حقيقةً، بل ﴿لَّعَنَهُمُ ٱللَّهُ﴾؛ أي: طردهم الملك الأعظم عن قبول ذلك؛ لأنهم ليسوا بأهل للسعادة بعد أن خلقهم على الفطرة الأولى القويمة لا غلف على قلوبهم؛ لأن اللعن إبعاد في المعنى والمكانة. البقاعي: ١/١٨٢.\nلماذا لعنهم الله وأبعدهم عن رحمته؟"],[14,"§البقرة\nwords\nيَستَفتِحُونَيَستَنصِرُونَ بِهِ عَلَى المُشرِكِينَ.\nفَبَاءُوارَجَعُوا.\ndeeds\nاستعذ بالله من البغي والحسد.\nاسأل الله سبحانه أن يرزقك التواضع، ودرِّب نفسك عليه؛ فإنه مفتاح الخير، كما أن الكبر مفتاح الشر.\nقل هذا الدعاء وحافظ عليه: \"اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك\"؛ فإن اليهود لمَّا سخط الله عليهم فضح عيوبهم وأسرارهم على رؤوس الخلائق.\nguid\nحسد الآخرين على فضل الله عليهم عاقبته غضب الله تعالى، والعذاب المهين.\nعليك أن تتمسك بدينك بقوة؛ فإن المؤمن القوي المتمسك بدينه خيرٌ من المؤمن الضعيف.\nالإصرار على العناد يؤدي إلى أن يتشربه قلب المعاند، ويصبح كأنه حقيقة لديه.\nrefl\nفَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ ٨٩\nكفرهم كان لمجرد العناد الذي هو نتيجة الحسد لا للجهل، وهو أبلغ في الذم؛ لأن الجاهل قد يعذر. الألوسي: ١/٣٢٢.\nما سبب كفر اليهود؟\nبِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ ٱللَّهُ بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ ٩٠\nلما كان كفرهم سببه البغي والحسد، ومنشأ ذلك التكبر؛ قوبلوا بالإهانة والصغار في الدنيا والآخرة. ابن كثير: ١/١٢٠.\nالجزاء من جنس العمل؛ وضّح ذلك من الآية.\nفَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٖۚ\nفلعنهم الله، وغضب عليهم غضبًا بعد غضب؛ لكثرة كفرهم، وتوالي شكهم وشركهم. السعدي: ٥٩.\nلماذا باء اليهود بغضب بعد غضب؟\nوَهُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا مَعَهُمۡۗ\nفلِمَ تؤمنون بما أنزل عليكم، وتكفرون بنظيره؟ هل هذا إلا تعصب واتباع للهوى؟ السعدي: ٥٩.\nبيَّن القرآن أن سبب كفرهم بالقرآن إنَّما هو التعصب والهوى، وضِّح ذلك من خلال الآية.\nقُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم مُّؤۡمِنِينَ ٩١\nفي إضافة (أنبياء) إلى الاسم الكريم تشريف عظيم، وإيذان بأنه كان ينبغي لمن جاء من عند الله تعالى أن يُعظَّم ويُنصَر، لا أن يُقتَل. الألوسي: ١/٣٢٤.\nعلى ماذا تدل إضافة اسم أحد المخلوقات إلى اسم الله تعالى؟\nوَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱسۡمَعُواْۖ\n﴿وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ﴾: الجبل العظيم؛ الذي جعلناه زاجرًا لكم عن الرضا بالإقامة في حضيض الجهل، ورافعًا إلى أوج العلم... ومن سمع فلم يقبل كان كمن لم يسمع. قال: (واسمعوا): وإلا دفناكم به؛ وذلك حيث يكفي غيركم في التأديب رفع الدرة والسوط عليه فينبعث للتعلم. البقاعي: ١/١٩٨.\nتأديب المعاند على قدر عناده، إلى أي مدى بلغ تأديب اليهود؟\nخُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱسۡمَعُواْۖ\nأي: سماع قبول، وطاعة، واستجابة. السعدي: ٥٩.\nما نوع السماع الذي أراده الله سبحانه منا للقرآن الكريم؟"],[15,"§البقرة\nwords\nبِمُزَحزِحِهِبِمُبعِدِهِ.\nنَبَذَهُطَرَحَهُ.\ndeeds\nضع مخططًا لحياتك، واجعل فيه عملًا صالحًا كبيرًا يجعلك تشتاق للآخرة.\nسل الله تعالى حسن الخاتمة، والشوق للقاء الله في غير ضراء مضرة، ولا فتنة مضلة.\nراجع قائمة زملائك وأصدقائك، وحاول أن تدخل فيهم من تظن أنه من أولياء الله سبحانه.\nguid\nكلما كثرت ذنوب العبد اشتدت غفلته عن الموت وذكره.\nمن أحبه الله أحبته الملائكة.\nاحذر أن تكون عدوًا لأولياء الله؛ فإن الله تعالى يعادي من يعادي أولياءه.\nrefl\nقُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةٗ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ ٩٤\nلأن من اعتقد أنه من أهل الجنة كان الموت أحب إليه من الحياة في الدنيا؛ لما يصير إليه من نعيم الجنة، ويزول عنه من أذى الدنيا. القرطبي: ٢/٢٥٧.\nلماذا أمر الله تعالى اليهود أن يتمنوا الموت؟\nقُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةٗ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ ٩٤\nلأن ذلك علم على صلاح حال العبد مع ربه، وعمارة ما بينه وبينه ورجائه للقائه؛... فعلى قدر نفرة النفس من الموت يكون ضعف منال النفس مع المعرفة التي بها تأنس بربها فتتمنى لقاءه وتحبه، ومن أحب لقاء الله أحب الله لقاءه، ومن كره لقاء الله كره الله لقاءه. البقاعي: ١/٢٠٠.\nما دلالة تمني لقاء الله؟\nوَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٖ وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَمَّرُ أَلۡفَ سَنَةٖ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ ٩٦\nذمهم بتهالكهم على بقائهم في الدنيا على أي حالة كانت؛ علمًا منهم بأنها -ولو كانت أسوأ الأحوال- خير لهم مما بعد الموت. البقاعي: ١/٢٠٢.\nما سبب حرصهم على البقاء في الدنيا على أية حال؟\nوَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ ٩٦\n﴿وَمَا هُوَ بِمُزَحۡزِحِهِۦ﴾: مباعده. ﴿مِنَ ٱلۡعَذَابِ﴾: من النار. ﴿أَن يُعَمَّرَۗ﴾؛ أي: طول عمره لا ينقذه. البغوي: ١/٧٩.\nهل طول العمر منقذ للعبد من عذاب الله تعالى؟\nقُلۡ مَن كَانَ عَدُوّٗا لِّـجِبۡرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ\nوخص القلب بالذكر؛ لأنه موضع العقل والعلم وتلقي المعارف. القرطبي: ٢/٢٦٢.\nبيّن ما يدل على أهمية القلب وعظيم شأنه.\nفَإِنَّ ٱللَّهَ عَدُوّٞ لِّلۡكَٰفِرِينَ ٩٨\nمن عادى وليًا لله فقد عادى الله، ومن عادى الله فإن الله عدوٌ له، ومن كان الله عدوه فقد خسر الدنيا والآخرة. ابن كثير: ١/١٢٧.\nما خطورة معاداة أولياء الله سبحانه؟\nوَلَمَّا جَآءَهُمۡ رَسُولٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ ١٠١\nقال سفيان بن عيينة: أدرجوها في الحرير والديباج، وحلوها بالذهب والفضة، ولم يعملوا بها؛ فذلك نبذهم لها. البغوي: ١/٨٢\nما الإكرام الحقيقي، وما النبذ الحقيقي لكتاب الله تعالى؟"],[16,"§البقرة\nwords\nاشتَرَاهُاختَارَهُ.\nخَلاَقٍنَصِيبٍ.\nرَاعِنَاكَلِمَةٌ كَانَ اليَهُودُ يَقُولُونَهَا لِلنَّبِيِّ صلّى الله عليه وسلّم بِقَصدِ السَّبِّ، وَنِسبَتِهِ إِلَى الرُّعونَةِ.\ndeeds\nاستـعذ بالله من شـر حـاسـد إذا حسـد، ومن شـر النفـاثات في العقد.\nاسعَ في صلح بين اثنين؛ وخاصة زوجين، واعلم أن الشيطان وجنده يسعون للإفساد بين الناس والأزواج، فكن أنت مصلحًا.\nحذر المجتمع من وجود السحرة فيه، ووضح خطرهم عليه ووجوب السعي والتعاون لكف شرهم.\nguid\nكفر الساحر، وتحريم تعلُّم السحر واستعماله.\nمن تعلق بالله كفاه الله شر كل ذي شر.\nداء الحسد عنصر مؤثر في علاقات أهل الكتاب مع أمة محمد -صلى الله عليه وسلم-.\nrefl\nوَمَا كَفَرَ سُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ\nويستعان في تحصيله بالتقرب إلى الشيطان بارتكاب القبائح: قولًا؛ كالرقى التي فيها ألفاظ الشرك، ومدح الشيطان، وتسخيره، وعملًا؛ كعبادة الكواكب، والتزام الجناية، وسائر الفسوق. الألوسي: ١/٣٣٨.\nلا يتعلم السحر إلا بشرك وكفر؛ وضّح ذلك من الآية.\nوَمَا كَفَرَ سُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ\nكما أن الملائكة لا تعاون إلا أخيار الناس المشبهين بهم في المواظبة على العبادة، والتقرب إلى الله تعالى بالقول والفعل؛ كذلك الشياطين لا تعاون إلا الأشرار المشبهين بهم في الخباثة والنجاسة قولًا وفعلًا واعتقادًا؛ وبهذا يتميز الساحر عن النبي والولي. الألوسي: ١/٣٣٨.\nما علاقة كل من الملائكة والشياطين بالبشر؟\nوَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ\nوفي هذه الآية وما أشبهها: أن الأسباب مهما بلغت في قوة التأثير فإنها تابعة للقضاء والقدر، ليست مستقلة في التأثير. السعدي: ٦١.\nما النظرة السليمة التي يجب أن يكون عليها المسلم تجاه الأسباب؟\nوَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ\nيتعلمون منهما السحر الذي يضرهم في دينهم، ولا ينفعهم في معادهم. الطبري: ٢/٤٥٠.\nما المراد بالنفع المنفي من الآية؟\nوَلَقَدۡ عَلِمُواْ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖۚ وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ ١٠٢\nالسحر لا ينفع في الآخرة، ولا يُقرّب إلى الله، وأنّ من اشتراه ما له في الآخرة من خلاق؛ فإنّ مبناه على الشرك والكذب والظلم، ومقصود صاحبه الظلم والفواحش. ابن تيمية: ٢/٢٨٧.\nلماذا السحر لا ينفع، ولا يقرب إلى الله تعالى؟\nوَلَوۡ أَنَّهُمۡ ءَامَنُواْ وَٱتَّقَوۡاْ لَمَثُوبَةٞ مِّنۡ عِندِ ٱللَّهِ خَيۡرٞۚ لَّوۡ كَانُواْ يَعۡلَمُونَ ١٠٣\n﴿لَمَثُوبَةٌ مِّنۡ عِندِ ٱللَّهِ﴾: لم يقل: لمثوبة الله - مع أنه أخصر - ليشعر التنكير بالتقليل؛ فيفيد أن شيئًا قليلًا من ثواب الله تعالى في الآخرة الدائمة خير من ثواب كثير في الدنيا الفانية، فكيف وثواب الله تعالى كثير دائم؟! الألوسي: ١/٣٤٧\nلماذا وردت كلمة (مثوبة) في الآية نكرة، ولم تضف إلى لفظ الجلالة؟\nيٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ٱنظُرۡنَا وَٱسۡمَعُواْ\nكان المسلمون يقولون حين خطابهم للرسول عند تعلمهم أمر الدين: (راعنا)؛ أي: راع أحوالنا؛ فيقصدون بها معنىً صحيحًا. وكان اليهود يريدون بها معنىً فاسدًا، فانتهزوا الفرصة، فصاروا يخاطبون الرسول بذلك، ويقصدون المعنى الفاسد، فنهى الله المؤمنين عن هذه الكلمة سدًّا لهذا الباب؛ ففيه: النهي عن الجائز إذا كان وسيلة إلى محرم. السعدي: ٦١.\nاستنبط من الآية أحد الآداب الإسلامية في مخاطبة الآخرين."],[17,"§البقرة\nwords\nنَنسَخنُزِل، وَنَرفَع.\nنُنسِهَانَمحُهَا مِنَ القُلُوبِ.\nسَوَاءَ السَّبِيلِوَسَطَ الطَّرِيقِ، وَهُوَ الصِّرَاطُ المُستَقِيمُ.\ndeeds\nاستعذ بالله من الحسد، وكن على حذر من أهله.\nأرسل رسالة، أو اكتب مقالةً تبين فيها أن كثيرًا من اليهود والنصارى يودون انحراف المسلمين عن دينهم؛ كما أخبر القرآن بذلك.\nبادر إلى الصلوات الخمس في وقتها.\nguid\nالنسخ في الأحكام نوع من التدرج في التشريع، وهو رحمة من الله تعالى بالمؤمنين.\nكن على يقين أن الخير فيما اختاره الله، والشر فيما حرمه الله سبحانه.\nالعفو والصفح من أخلاق المسلمين العظيمة، سواء مع المسلمين، أو مع غيرهم.\nrefl\nمَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ١٠٦\nمعرفة هذا الباب أكيدة، وفائدته عظيمة، لا يستغني عن معرفته العلماء، ولا ينكره إلا الجهلة الأغبياء، لما يترتب عليه من النوازل في الأحكام، ومعرفة الحلال من الحرام. القرطبي: ٢/٣٠٠.\nما أهمية معرفة باب النسخ في الشريعة ودراسته لمن يريد استنباط الأحكام الشرعية؟\n\" أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَوَاتِ وَالأَرْضِ وَمَا لَكُمْ مِنْ دُونِ اللَّهِ مِنْ وَلِيٍّ وَلا نَصِيرٍ ١٠٧\nفمن علم أنه تعالى وليه ونصيره -لا ولي ولا نصير له سواه- يعلم قطعًا أنه لا يفعل به إلا ما هو خير له؛ فيفوض أمره إليه تعالى. الألوسي: ١/٣٥٤.\nما فائدة الإيمان بولاية الله تعالى ونصرته؟\nأَمۡ تُرِيدُونَ أَن تَسۡٔلُواْ رَسُولَكُمۡ كَمَا سُئِلَ مُوسَىٰ مِن قَبۡلُۗ\nوالمراد بذلك أسئلة التعنت والاعتراض... وأمَّا سؤال الاسترشاد والتعلم فهذا محمود قد أمر الله به. السعدي: ٦٢.\nمتى تكون الأسئلة الشرعية محمودة؟ ومتى تكون مذمومة؟\nوَدَّ كَثِيرٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يَرُدُّونَكُم مِّنۢ بَعۡدِ إِيمَٰنِكُمۡ كُفَّارًا حَسَدٗا مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡحَقُّۖ\n﴿وَدَّ كَثِيرٌ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ﴾؛ أي: تمنوا. ونزلت الآية في حيي بن أخطب وأخيه أبي ياسر، وأشباههما من اليهود؛ الذين كانوا يحرصون على فتنة المسلمين، ويطمعون أن يردّوهم عن الإسلام حَسَدًا. ابن جزي: ١/٧٨.\nما رأيك فيمن يهوّن من عداوة أهل الكتاب للمسلمين، ويتهم المسلمين بنظرية المؤامرة؟\nبَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ فَلَهُۥٓ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ١١٢\n﴿بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ﴾؛ يقول: من أخلص لله... ﴿وَهُوَ مُحۡسِنٌ﴾؛ أي: اتبع فيه الرسول -صلى الله عليه وسلم- فإن للعمل المتقبل شرطين: أحدهما: أن يكون خالصًا لله وحده، والآخر: أن يكون صوابًا موافقًا للشريعة، فمتى كان خالصًا ولم يكن صوابًا لم يُتَقَبَّل. ابن كثير: ١/١٤٧.\nما شروط قبول العمل؟ وما الدليل عليها؟\nبَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ فَلَهُۥٓ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ١١٢\n﴿مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ﴾؛ أي: أخلص لله أعماله، متوجهًا إليه بقلبه ﴿وَهُوَ مُحۡسِنٌ﴾ في عبادة ربه؛ بأن عبده بشرعه، فأولئك هم أهل الجنة وحدهم... ويُفهم منها أن من ليس كذلك فهو من أهل النار الهالكين، فلا نجاة إلا لأهل الإخلاص للمعبود، والمتابعة للرسول. السعدي: ٦٤.\nلماذا يُرَد عمل الرياء؟ ولماذا تُرَد البدع فلا تقبل عند الله؟\nبَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ فَلَهُۥٓ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ١١٢\nوإنَّما يدخل الجنة من أسلم وجهه لله؛ أي:أخلص دينه لله، وقيل: أخلص عبادته لله، وقيل: خضع وتواضع لله. وأصل الإسلام: الاستسلام والخضوع، وخص الوجه؛ لأنه إذا جاد بوجهه في السجود لم يبخل بسائر جوارحه. البغوي: ١/٩٣.\nمن المستحق لدخول الجنة فضلًا من الله وكرمًا؟"],[18,"§البقرة\nwords\nقَانِتُونَخَاضِعُونَ، مُنقَادُونَ.\nبَدِيعُالخَالِقُ عَلَى غَيرِ مِثَالٍ سَابِقٍ.\ndeeds\nتعاون مع إخوانك في ترتيب المسجد، وتهيئة أسباب الترغيب فيه؛ فذلك من تعظيم شعائر الله.\nاجلس في المسجد ذاكرًا الله تعالى من الصلاة إلى الصلاة.\nأحيِ السنة، وصلِّ النافلة حيث توجهت السيارة أو الطائرة أو السفينة التي تركبها.\nguid\nتضليل الآخرين وتبديعهم لا بد له من أدلة صحيحة.\nاحذر أن تكون سببًا في منع إقامة طاعةٍ من الطاعات في بيوت الله، فهذا من أشد الظلم.\nجاء رسولنا الكريم -صلى الله عليه وسلم- بالبشارة والنذارة؛ فمن اهتم بالبشارات وحدها فقد أخطأ، ومن اهتم بالنذارات وحدها فقد أخطأ، ومن جمع بينهما فقد أصاب.\nrefl\nوَقَالَتِ ٱلۡيَهُودُ لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءٖ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيۡسَتِ ٱلۡيَهُودُ عَلَىٰ شَيۡءٖ وَهُمۡ يَتۡلُونَ ٱلۡكِتَٰبَۗ\nفهم -كما قال الإمام أحمد-... \"مختلفون في الكتاب، مخالفون للكتاب، مجمعون على مفارقة الكتاب\" ـ قد جمعوا وصفي الاختلاف الذي ذمه الله في كتابه؛ فإنه ذم الذين خالفوا الأنبياء، والذين اختلفوا على الأنبياء. ابن تيمية: ١/٣١١.\nجمع اليهود والنصارى وصفي الاختلاف؛ فما هما؟\nوَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذۡكَرَ فِيهَا ٱسۡمُهُۥ وَسَعَىٰ فِي خَرَابِهَآۚ\nوإذا كان لا أظلم ممن منع مساجد الله أن يذكر فيها اسمه؛ فلا أعظم إيمانًا ممن سعى في عمارة المساجد بالعمارة الحسية والمعنوية؛ كما قال تعالى: ﴿إِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ﴾ [التوبة: ١٨]. السعدي: ٦٣.\nكلٌ من عمارة المساجد، أو تخريبها له شأن عظيم عند الله سبحانه، وضِّح ذلك.\nوَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذۡكَرَ فِيهَا ٱسۡمُهُۥ وَسَعَىٰ فِي خَرَابِهَآۚ\nمن أعلام قيام الساعة: تضييع المساجد؛ لذلك كل أمة وكل طائفة وكل شخص معين تطرق بجُرم في مسجد يكون فعله سببًا لخلائه فإن الله -عز وجل- يعاقبه بروعة ومخافة تناله في الدنيا. البقاعي: ١/٢٢٥.\nمن علامات قيام الساعة تضييع المساجد، فكيف يكون تضييعها؟\nوَسَعَىٰ فِي خَرَابِهَآۚ\n(وسعى)؛ أي: اجتهد وبذل وسعه. ﴿فِي خَرَابِهَآۚ﴾: الحسي والمعنوي؛ فالخراب الحسي: هدمها وتخريبها، وتقذيرها، والخراب المعنوي: منع الذاكرين لاسم الله فيها. وهذا عام لكل من اتصف بهذه الصفة. السعدي: ٦٣.\nتخريب المساجد؟ وأيهما أكثر انتشارًا في الأمة اليوم؟\nوَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ\nيطلبون آيات التعنت، لا آيات الاسترشاد، ولم يكن قصدهم تبيُّن الحق؛ فإن الرسل قد جاؤوا من الآيات بما يؤمن بمثله البشر. السعدي: ٦٤.\nقد طلب الكفار آياتٍ ولم يستجب الله لهم؛ فلماذا؟\nوَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَٰبَهَتۡ قُلُوبُهُمۡۗ\n﴿تَشَٰبَهَتۡ قُلُوبُهُمۡۗ﴾: الضمير للذين لا يعلمون وللذين من قبلهم، وتشابه قلوبهم في الكفر، أو في طلب ما لا يصح أن يُطلب. ابن جزي:١/ ٨١.\nفي أي شيء تتشابه قلوب ﴿ٱلَّذِينَ لَا يَعۡلَمُونَ﴾ مع قلوب ﴿ٱلَّذِينَ مِن قَبۡلِهِم﴾؟\nإِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۖ وَلَا تُسۡٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ ١١٩\nالمراد: إنا أرسلناك لأن تبشر من أطاع وتنذر من عصى، لا لتجبر على الإيمان، فما عليك إن أصروا أو كابروا. الألوسي:١/٣٧٠.\nماذا يستفيد الداعية من هذه الآية؟"],[19,"§البقرة\nwords\nمَثَابَةًمَرجِعًا يَأتُونَهُ، ثُمَّ يَرجِعُونَ إِلَى أَهلِيهِم.\nأَضطَرُّهُأُلجِئُهُ.\nالمَصِيرُالمَرجِعُ، وَالمَقَامُ.\ndeeds\nاكتب رسالةً أو مقالًا تبين فيه شدة عداء عموم اليهود والنصارى، وأن غاية رغبتهم تركنا للدين، مستدلًا بالآية وشواهد الواقع المعاصر.\nضع لك طريقة وحافظ عليها عند تلاوة القرآن الكريم أو حفظه؛ وهي أن تستخرج عملًا من الآيات، وتطبقه.\nقل: \"ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إمـامًا\".\nguid\nلا يمكن للمسلم أن يحصل على الرضا التام من غير المسلمين إلا بأن يدخل في دينهم؛ فليبحث عن رضا الله سبحانه فقط.\nليس هناك هدىً إلا في كلام الله سبحانه وكلام رسوله -صلى الله عليه وسلم-؛ فاجتهد في تأملهما.\nكان إبراهيمُ إمامًا للمصلحين والمهتدين؛ بسبب قيامه بشريعة الله أتم قيام؛ فمن أراد أن يكون إمامًا فليعمل بعلمه.\nrefl\nوَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ\nفدع طلب ما يرضيهم ويوافقهم، وأقبل على طلب رضا الله في دعائهم إلى ما بعثك الله به من الحق. ابن كثير: ١/١٥٥.\nإذا كان اليهود والنصارى لن يرضوا عنك، فما الواجب عليك تجاههم؟\nوَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ\nليس غرضهم يا محمد بما يقترحون من الآيات أن يؤمنوا، بل لو أتيتهم بكل ما يسألون لم يرضوا عنك، وإنَّما يرضيهم ترك ما أنت عليه من الإسلام واتباعهم. القرطبي: ٢/٣٤٥.\nما هدف اليهود والنصارى في طلباتهم من المسلمين؟\nٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۗ\nوتلاوة الكتاب هي اتباعه؛ كما قال ابن مسعود في قوله تعالى: ﴿ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ﴾ قال: \"يحللون حلاله، ويحرمون حرامه، ويؤمنون بمتشابهه ويعملون بمحكمه\". ابن تيمية: ١/٣٣٩.\nكيف تكون تلاوة الكتاب حق تلاوته؟\nوَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ ١٢٤\nاستدل جماعة من العلماء بهذه الآية على أن الإمام يكون من أهل العدل والإحسان والفضل مع القوة على القيام بذلك... فأما أهل الفسوق والجور والظلم فليسوا له بأهل؛ لقوله تعالى: ﴿لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ﴾. القرطبي: ٢/٣٧٠.\nما شرط تولي المناصب القيادية للمسلمين؟\nوَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةٗ لِّلنَّاسِ وَأَمۡنٗا\n(مثابة) أي: مرجعًا يرجعون إليه بكلياتهم؛ كلما تفرقوا عنه اشتاقوا إليه، هم أو غيرهم، آية على رجوعهم من الدنيا إلى ربهم. البقاعي: ١/٢٣٩.\nما دلالة قوله تعالى: ﴿مَثَابَةً لِّلنَّاسِ﴾؟\nأَن طَهِّرَا بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ ١٢٥\n﴿وَٱلرُّكَّعِ ٱلسُّجُودِ﴾: لأنهما أقرب أحواله إليه تعالى، وهما الركنان الأعظمان، وكثيرًا ما يُكنى عن الصلاة بهما. الألوسي: ١/٣٨١.\nللركوع والسجود أهمية على بقية أعمال الصلاة، كيف عرفت ذلك؟\nوَإِذۡ قَالَ إِبۡرَٰهِۧمُ رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنٗا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلٗا ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ ١٢٦\nتعليم تعميم دعاء الرزق، وأن لا يحجر في طلب اللطف؛ وكأن إبراهيم -عليه السلام- قاس الرزق على الإمامة؛ فنبهه سبحانه على أن الرزق رحمة دنيوية لا تخص المؤمن بخلاف الإمامة. الألوسي: ١/٣٨٢.\nهل رزق الله في الدنيا خاص بالمؤمنين؟"],[20,"§البقرة\nwords\nالقَوَاعِدَالأُسُسَ.\nوَأَرِنَا مَنَاسِكَنَابَصِّرنَا بِمَعَالِمِ عِبَادَتِنَا لَكَ.\nوَيُزَكِّيهِميُطَهِّرُهُم مِنَ الشِّركِ وَسُوءِ الأَخلاَقِ.\nيَرغَبُيُعرِضُ وَيَنصَرِفُ.\nسَفِهَ نَفسَهُسَفِيهٌ، جَاهِلٌ.\ndeeds\nتذكر أعمال خير عملتها، ومع تذكر كل عمل كرر قول: \"ربنا تقبل منا؛ إنك أنت السميع العليم\".\nادعُ اليوم بدعاء واشمل به ذريتك، وأشركهم فيه.\nمع محافظتك على تلاوة القرآن الكريم؛ حاول أن تبدأ اليوم بقراءة في كتب السنة؛ خاصة صحيحي البخاري ومسلم.\nguid\nالدعاء بالصلاح والاستقامة للذرية شأن الأنبياء والصالحين بعدهم.\nكلما عملت عملًا تتعبد الله فيه فادعُ بهذا الدعاء.\nلقد كانت الأنبياء تسأل الله التوبة؛ فنحن أولى منهم بذلك.\nrefl\nوَإِذۡ يَرۡفَعُ إِبۡرَٰهِۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ\n﴿تَقَبَّلۡ مِنَّآۖ﴾ أي: عاملنا بفضلك، ولا ترده علينا؛ إشعارًا بالاعتراف بالتقصير؛ لحقارة العبد -وإن اجتهد- في جنب عظمة مولاه. البقاعي: ١/٢٤٢.\nلماذا دعى إبراهيم وإسماعيل بالقبول؟\nوَإِذۡ يَرۡفَعُ إِبۡرَٰهِۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ١٢٧\nوآثر صيغة المضارع مع أن القصة ماضية استحضارًا لهذا الأمر؛ ليقتدي الناس به في إتيان الطاعات الشاقة مع الابتهال في قبولها، وليعلموا عظمة البيت المبني؛ فيعظموه. الألوسي: ١/٣٨٣.\nلماذا آثر صيغة المضارع (يرفع) مع أن القصة ماضية؟\nرَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ ١٢٨\nولما كان العبد -مهما كان- لا بد أن يعتريه التقصير ويحتاج إلى التوبة، قالا: ﴿وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾. السعدي: ٦٦.\nلماذا طلبا التوبة من الله -سبحانه وتعالى- مع مكانتهما العلية في الدين؟\nرَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ\nالتوبة تختلف باختلاف التائبين؛ فتوبة سائر المسلمين: الندم، والعزم على عدم العود، ورد المظالم إذا أمكن، ونية الرد إذا لم يمكن. وتوبة الخواص: الرجوع عن المكروهات من خواطر السوء، والفتور في الأعمال، والإتيان بالعبادة على غير وجه الكمال. وتوبة خواص الخواص: لرفع الدرجات، والترقي في المقامات. الألوسي: ١/٣٨٦.\nهل تختلف التوبة باختلاف الأشخاص؟ وضح ذلك.\nرَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ\nوالحكمة: المعرفة بالدين، والفقه في التأويل، والفهم الذي هو سجية ونور من الله تعالى. القرطبي: ٢/٤٠٣.\nما الحكمة التي دعا بها نبي الله إبراهيم -عليه السلام-؟\nرَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُزَكِّيهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ١٢٩\n(الحكمة) هي: السنة؛ لأن الله أمر أزواج نبيه أن يذكرن ما يتلى في بيوتهن من الكتاب والحكمة، والكتاب: القرآن، وما سوى ذلك مما كان الرسول يتلوه هو السنة. ابن تيمية: ١/٣٤٥.\nما المقصود بالحكمة؟ وما الدليل؟\nفَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ ١٣٢\nفقوموا به، واتصفوا بشرائعه، وانصبغوا بأخلاقه، حتى تستمروا على ذلك، فلا يأتيكم الموت إلا وأنتم عليه؛ لأن من عاش على شيء مات عليه، ومن مات على شيء بُعث عليه. السعدي: ٦٧.\nكيف أمرهم بالموت على الإسلام والإنسان لا يملك نفسه حال موته؟"],[21,"§البقرة\nwords\nوَالأَسبَاطِالأَنبِيَاءِ مِن وَلَدِ يَعقُوبَ، الَّذِينَ كَانُوا فِي قَبَائِلِ بَنِي إِسرَائِيلَ.\nشِقَاقٍخِلاَفٍ شَدِيدٍ.\nصِبغَةَ اللَّهِالزَمُوا دِينَ اللهِ وَفِطرَتَهُ.\ndeeds\nاسأل الله تعالى الهداية دائمًا.\nاقرأ في الركعة الأولى من سنة الفجر هذه الآية.\nأعلن الحق للناس، وأظهر التزامك به؛ فهو أدعى للثبات عليه، وقبول الناس له.\nguid\nعلى المؤمن أن لا يهتم بالشعارات والادعاءات، ولا تغريه الكلمات، بل عليه أن يبحث عن الحقائق المؤيدة بالأدلة الصحيحة.\nلا هداية ولا سعادة في الدارين إلا بالإسلام.\nلا بد للمسلم أن يظهر عقيدته الصحيحة، ويصدع بها، ويدعو لها؛ إذ هي أصل الدين وأساسه.\nrefl\nقُولُوٓاْ ءَامَنَّا بِٱللَّهِ\nأي: بألسنتكم متواطئة عليها قلوبكم، وهذا هو القول التام المترتب عليه الثواب والجزاء؛ فكما أن النطق باللسان بدون اعتقاد القلب نفاق وكفر، فالقول الخالي من العمل-عمل القلب- عديم التأثير، قليل الفائدة. السعدي: ٦٧.\nهل المراد بالإيمان مجرد القول؟\nقُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِيَ ٱلنَّبِيُّونَ مِن رَّبِّهِمۡ\nوقدم الإيمان بالله؛ لأنه لا يختلف باختلاف الشرائع الحق، ثم عطف عليه الإيمان بما أنزل من الشرائع. ابن عاشور: ١/٧٣٩.\nلماذا قدم الإيمان بالله تعالى على الإيمان بالشرائع؟\nوَمَآ أُوتِيَ ٱلنَّبِيُّونَ مِن رَّبِّهِمۡ\nدلالة على أن عطية الدين هي العطية الحقيقية المتصلة بالسعادة الدنيوية والأخروية؛ لم يأمرنا أن نؤمن بما أُوتي الأنبياء من الملك والمال ونحو ذلك، بل أمرنا أن نؤمن بما أُعطوا من الكتب والشرائع. السعدي: ٦٨.\nمن أكثر الناس حظًا في عطايا الله سبحانه؟\nفَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا هُمۡ فِي شِقَاقٖۖ فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ١٣٧\n(فسيكفيكهم): وعد ظهر مصداقه؛ فقتل بني قريظة، وأجلى بني النضير، وغير ذلك. ابن جزي: ١/٨٥.\nعدد ثلاثة مواطن من مواطن كفاية الله لنبيه من أذى الكفار.\nصِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةٗۖ وَنَحۡنُ لَهُۥ عَٰبِدُونَ ١٣٨\nأي: الزموا صبغة الله، وهو دينه، وقوموا به قيامًا تامًا بجميع أعماله الظاهرة والباطنة، وجميع عقائده في جميع الأوقات، حتى يكون لكم صبغةً وصفةً من صفاتكم، فإذا كان صفة من صفاتكم أوجب ذلك لكم الانقياد لأوامره؛ طوعًا واختيارًا ومحبةً، وصار الدين طبيعة لكم بمنزلة الصبغ التام للثوب الذي صار له صفة؛ فحصلت لكم السعادة الدنيوية والأخروية. السعدي: ٦٨.\nلماذا سُمِّيَ الدين بصبغة الله؟\nوَنَحۡنُ لَهُۥ عَٰبِدُونَ ١٣٨\nقال سعيد بن جبير: \"الإخلاص أن يخلص العبد دينه وعمله لله؛ فلا يشرك به في دينه، ولا يرائي بعمله\"، قال الفضيل: \"ترك العمل لأجل الناس رياء، والعمل من أجل الناس شرك، والإخلاص أن يعافيك الله منهما\". البغوي: ١/١١٣.\nما حقيقة الإخلاص لله تعالى؟\nتِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ ١٤١\nكررها؛ لأنها تضمنت معنى التهديد والتخويف؛ أي: إذا كان أولئك الأنبياء على إمامتهم وفضلهم يُجازون بكسبهم فأنتم أحرى. القرطبي: ٢/٤٢٥.\nذكرت هذه الآية من قبل (آية ١٣٤)؛ فلم ذكرت هنا مرة أخرى؟"],[22,"§البقرة\nwords\nيَنقَلِبُ عَلَى عَقِبَيهِيَرتَدُّ عَن دِينِهِ\ndeeds\nافتعال الأزمات وتضخيم القضايا شأن المنافقين والكفار، حذر المجتمع برسالة فيها ثلاث قضايا استخدم الإعلام فيها هذه الأساليب.\nحدد فتنة التبس فيها الحق على المسلمين، واسأل الله تعالى الهداية والتوفيق فيها.\nانصح أحد المقصرين في صلاتهم، وبين له أن الله سمى الصلاة إيمانًا، وأنه قد كتب واقع كل مسلم مع الصلاة ليحاسبه عليها.\nguid\nالسفيه هو الذي يعترض على حكم الله تعالى.\nاختبار إيمانك هو أن تعمل بما أمرك الله تسليمًا له، راضيًا بحكمه، عرفت الحكمة أو لم تعرف.\nفرقٌ بين تأليف قلوب المدعوين واتباع أهوائهم بسخط الله.\nrefl\nسَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ\nالعاقل لا يبالي باعتراض السفيه، ولا يلقي له ذهنه، ودلت الآية على أنه لا يعترض على أحكام الله إلا سفيه جاهل معاند، وأمَّا الرشيد المؤمن العاقل فيتلقى أحكام ربه بالقبول والانقياد والتسليم؛ كما قال تعالى: ﴿وَمَا كَانَ لِمُؤۡمِنٖ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡ﴾ [الأحزاب:٣٦]، ﴿فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ﴾ [النساء:٦٥]. السعدي: ٧٠.\nسَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ\nوتقديم الإخبار بالقول على الوقوع لتوطين النفس به؛ فإن مفاجأة المكروه أشد إيلامًا، والعلم به قبل الوقوع أبعد من الاضطراب، ولما أن فيها إعداد الجواب؛ والجواب المعد قبل الحاجة إليه أقطع للخصم. الألوسي: ٢/٢.\nلماذا قدَّم الإخبار بقولهم قبل وقوع الحادثة؟\nسَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ\nوقد كان في قوله: (السفهاء) ما يغني عن رد قولهم، وعدم المبالاة به، ولكنه تعالى مع هذا لم يترك هذه الشبهة حتى أزالها وكشفها مما سيعرض لبعض القلوب من الاعتراض، فقال تعالى: (قل) لهم مجيبًا: ﴿لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ﴾. السعدي: ٧٠.\nهل يكفي وصف المعترضين على الأحكام الشرعية بالسفاهة عن الرد عليهم؟\nوَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا\nوالوسط هاهنا الخيار والأجود... ولمَّا جعل الله هذه الأمة وسطًا خَصَّها بأكمل الشرائع، وأقوم المناهج، وأوضح المذاهب. ابن كثير:١/١٨١.\nكيف تدل الآية على أفضلية دين الإسلام على غيره من الأديان؟\nوَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ\nلو أقام عليهم كل دليل على صحة ما جاءهم به لما اتبعوه وتركوا أهواءهم؛ كما قال تعالى: ﴿إِنَّ ٱلَّذِينَ حَقَّتۡ عَلَيۡهِمۡ كَلِمَتُ رَبِّكَ لَا يُؤۡمِنُونَ * وَلَوۡ جَآءَتۡهُمۡ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ﴾ [يونس: ٩٦]، ولهذا قال هاهنا: ﴿وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٍ مَّا تَبِعُواْ قِبۡلَتَكَۚ﴾. ابن كثير: ١/١٨٤.\nالهداية منةٌ من الله سبحانه وليست بمجرد الإقناع العقلي، وضح ذلك من الآية.\nوَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعٖ قِبۡلَةَ بَعۡضٖۚ\nبيان لتصلبهم في الهوى وعنادهم بأن هذه المخالفة والعناد لا يختص بك؛ بل حالهم فيما بينهم أيضًا كذلك؛ فإنكارهم ذلك ناشئ عن فرط العناد. الألوسي: ٢/١٢.\nهل مواقف الكفار والمنافقين وشبهاتهم ناتجة عن تفكير منطقي أو علمي؟ وضح ذلك.\nوَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ ١٤٥\nثم حذر تعالى عن مخالفة الحق الذي يعلمه العالم إلى الهوى؛ فإن العالم الحجة عليه أقوم من غيره. ابن كثير:١/١٨٤.\nلماذا خُصَّت حالة العلم بالذكر والتهديد والوعيد هنا؟"],[23,"§البقرة\nwords\nالمُمتَرِينَالشَّاكِّينَ.\ndeeds\nسابق اليوم إلى الصف الأول، أو كن أول من يتصدق بصدقة، أو أول من يقرأ قرآنًا؛ فإن للسابقين منزلةٌ ليست لغيرهم.\nقل: \"رب زدني زكاةً وعلمًا وحكمةً\".\nحافظ على أذكار الصباح والمساء وأدبار الصلوات، وعلِّمها غيرك.\nguid\nمن اكتفى بالحد الأدنى من فعل الخيرات ضعف نشاطه إلى حد العجز والكسل، ومن ألزم نفسه بسباق غيره ثبت وزادت منزلته عند ربه.\nلا يظن العبد أنه يستطيع الهرب من قدرة الله بالأسباب التي يفعلها؛ فالله تعالى قادر عليه؛ على كل حال، وفي كل مكان.\nأفضل علاجين عند نزول المصائب: الصبر، والصلاة.\nrefl\nفَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ\nمن سبق في الدنيا إلى الخيرات فهو السابق في الآخرة إلى الجنات؛ فالسابقون أعلى الخلق درجة... ويُستدل بهذه الآية الشريفة على الإتيان بكل فضيلة يتصف بها العمل؛ كالصلاة في أول وقتها، والمبادرة إلى إبراء الذمة من الصيام والحج والعمرة، وإخراج الزكاة، والإتيان بسنن العبادات وآدابها؛ فلله ما أجمعها وأنفعها من آية! السعدي: ٧٣.\nوَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ\nومن التفت بقلبه في صلاته إلى غير ربه لم تنفعه وجهة بدنه إلى الكعبة؛ لأن ذلك حكم حق، حقيقته توجه القلب، ومن التفت بقلبه إلى شيء من الخلق في صلاته فهو مثل الذي استدبر بوجهه عن شطر قبلته. البقاعي: ١/٢٧٢.\nما حقيقة التوجه للقبلة؟ ولماذا؟\nفَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ ١٥٢\nلكل ذكر خاصيته وثمرته: وأمَّا التهليل فثمرته التوحيد، أعني التوحيد الخاص؛ فإنّ التوحيد العام حاصل لكل مؤمن، وأمَّا التكبير فثمرته التعظيم والإجلال لذي الجلال، وأمَّا الحمد والأسماء التي معناها الإحسان والرحمة -كالرحمن الرحيم، والكريم، والغفار، وشبه ذلك- فثمرتها ثلاث مقامات؛ وهي: الشكر، وقوة الرجاء، والمحبة؛ فإنّ المحسن محبوب لا محالة. ابن جزي: ١/٨٨.\nلكل ذكر ثمرته الخاصة في قلب العبد؛ بيّن ذلك مع التمثيل.\nفَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ ١٥٢\nلكل ذكر خاصيته وثمرته... وأمَّا الأسماء التي معناها الاطلاع والإدراك -كالعليم، والسميع، والبصير، والقريب، وشبه ذلك- فثمرتها المراقبة، وأمَّا الصلاة على النبي -صلى الله عليه وسلم- فثمرتها شدّة المحبة فيه، والمحافظة على اتباع سنته، وأمَّا الاستغفار فثمرته الاستقامة على التقوى، والمحافظة على شروط التوبة مع [انكسار] القلب بسبب الذنوب المتقدّمة. ابن جزي: ١/٨٨.\nما أثر ذكر العبد لربه بصفات السميع والبصير والقريب؟\nوَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ ١٥٢ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ ١٥٣\nلما فرغ تعالى من بيان الأمر بالشكر؛ شرع في بيان الصبر والإرشاد والاستعانة بالصبر والصلاة؛ فإن العبد إما أن يكون في نعمة فيشكر عليها، أو في نقمة فيصبر عليها. ابن كثير: ١/١٨٧.\nالعبد لا يخلو من حالين؛ ما هما؟ وما الواجب عليه في كل منهما؟\nٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ\nإذا كانت صلاة العبد صلاة كاملة، مجتمعًا فيها ما يلزم فيها وما يُسَنُّ، وحصل فيها حضور القلب،... لا جرم أن هذه الصلاة من أكبر المعونة على جميع الأمور؛ فإن الصلاة تنهى عن الفحشاء والمنكر، ولأن هذا الحضور الذي يكون في الصلاة يوجب للعبد في قلبه وَصفًا وَدَاعِيًا يدعوه إلى امتثال أوامر ربه، واجتناب نواهيه؛ هذه هي الصلاة التي أمر الله أن نستعين بها على كل شيء. السعدي: ٧٥.\nكيف تكون الصلاة معينة للعبد على امتثال أوامر ربه واجتناب نواهيه؟\nإِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ ١٥٣\nهذه معية خاصة، تقتضي محبته ومعونته، ونصره وقربه، وهذه منقبة عظيمة للصابرين؛ فلو لم يكن للصابرين فضيلة إلا أنهم فازوا بهذه المعية من الله لكفى بها فضلًا وشرفًا. السعدي: ٧٥.\nماذا تقتضي المعية الخاصة؟ ومَن أهلها؟ وضِّح ذلك من الآية."],[24,"§البقرة\nwords\nيَلعَنُهُمُيَطرُدُهُم.\ndeeds\nاسأل الله تعالى الشهادة صادقًا من قلبك.\nقل عند سماع مصائب المسلمين في نشرات الأخبار: ﴿إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ﴾.\nاسأل الله العافية، ثم احفظ الذكر المستحب عند نزول المصيبة: «من أصابته مصيبة فقال: اللهم أجرني في مصيبتي، وأخلف لي خيرًا منها؛ أخلف الله له خيرًا ممَّا أصابه».\nguid\nقد يُبتلى المؤمن بالمصائب في النفس والأهل والمال؛ فيصبر؛ فترتفع درجته، ويعلو مقامه عند ربه.\nكتمان العلم والحق عاقبته اللعن والطرد من رحمة الله تعالى.\nعالم السوء يلعنه كل اللاعنين، وعالم الحق يستغفر له كل المستغفرين.\nrefl\nإِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ ١٥٣ وَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢ بَلۡ أَحۡيَآءٞ وَلَٰكِن لَّا تَشۡعُرُونَ ١٥٤\nإشارة إلى أن كون الله معهم لا يمنع أن يُستشهَد منهم شهداء، بل ذلك من ثمرات كون الله معهم؛ حيث يظفر من استشهد منهم بسعادة الأخرى، ومن بقي بسعادة الدارين. البقاعي: ١/٢٧٩.\nهل معية الله للمجاهدين الصابرين تمنع من استشهادهم؟\nوَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢ بَلۡ أَحۡيَآءٞ وَلَٰكِن لَّا تَشۡعُرُونَ ١٥٤\nومن المعلوم أن المحبوب لا يتركه العاقل إلا لمحبوب أعلى منه وأعظم؛ فأخبر تعالى أن من قُتل في سبيله -بأن قاتل في سبيل الله لتكون كلمة الله هي العليا ودينه الظاهر، لا لغير ذلك من الأغراض- فإنه لم تفُته الحياة المحبوبة، بل حصل له حياةٌ أعظم، وأكمل مما تظنون وتحسبون. السعدي: ٧٥.\nمتى يترك الإنسان محبوبه؟\nوَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّٰبِرِينَ ١٥٥\nقيل: إنَّما ابتلوا بهذا ليكون آية لمن بعدهم؛ فيعلموا أنهم إنَّما صبروا على هذا حين وضح لهم الحق، وقيل: أعلمهم بهذا ليكونوا على يقين منه أنه يصيبهم؛ فيوطنوا أنفسهم عليه، فيكون أبعد لهم من الجزع. وفيه تعجيل ثواب الله تعالى على العزم وتوطين النفس. القرطبي: ٢/٤٦٢.\nلماذا أعلم الله تعالى عباده بحصول الابتلاء عليهم؟\nوَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ\nالسرَّاء لو استمرت لأهل الإيمان ولم يحصل معها محنة؛ لحصل الاختلاط الذي هو فساد، وحكمة الله تقتضي تمييز أهل الخير من أهل الشر؛ هذه فائدة المحن، لا إزالة ما مع المؤمنين من الإيمان، ولا ردّهم عن دينهم؛ فما كان الله ليضيع إيمان المؤمنين. فأخبر في هذه الآية أنه سيبتلي عباده ﴿بِشَيۡءٍ مِّنَ ٱلۡخَوۡفِ﴾ من الأعداء (والجوع)؛ أي: بشيء يسير منهما؛ لأنه لو ابتلاهم بالخوف كله أو الجوع لهلكوا، والمحن تُمحِّص، لا تهلك. السعدي: ٧٦.\nلماذا كان الابتلاء بشيء من الخوف والجوع، ولم يكن به كله؟\nٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ ١٥٦\nأي: مملوكون لله، مدبَّرون تحت أمره وتصريفه؛ فليس لنا من أنفسنا وأموالنا شيء، فإذا ابتلانا بشيء منها فقد تصرف أرحم الراحمين بمماليكه وأموالهم؛ فلا اعتراض عليه. السعدي: ٧٦.\nلماذا كان من المناسب قول من أصابته مصيبة: ﴿إِنَّ ٱللَّهَ﴾؟\nٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ ١٥٦\n﴿إِنَّ ٱللَّهَ﴾ اللام للمِلك، والمالك يفعل في ملكه ما يشاء. (راجعون): تذكروا الآخرة لتهون عليهم مصائب الدنيا، وفي الحديث الصحيح أن رسول الله -صلى الله عليه وسلم- قال: «من أصابته مصيبة فقال: إنا لله وإنَّا إليه راجعون، اللهم أجرني في مصيبتي، وأخلف لي خيرًا منها؛ أَخلَف الله له خيرًا مما أصابه». قالت أمّ سلمة: فلما مات زوجي -أبو سلمة- قلت ذلك؛ فأبدلني الله به رسول الله -صلى الله عليه وسلم-. ابن جزي: ١/٨٩.\nما الدعاء المستحب قوله عند نزول المصيبة؟\nٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ ١٥٦\nجعل هذه الكلمات ملجأً لذوي المصائب، وعصمةً للممتَحَنين لمَّا جمعت من المعاني المباركة؛ وذلك توحيد الله، والإقرار له بالعبودية، والبعث من القبور، واليقين بأن رجوع الأمر كله إليه كما هو له. وقال سعيد بن جبير: \"لم يُعطَ هذه الكلمات نبي قبل نبينا، ولو عرفها يعقوب لَمَا قال: (يا أسفى على يوسف)\". ابن عطية: ١/٢٢٨.\nما الحكمة من تقرير هذا الدعاء عند المصائب؟"],[25,"§البقرة\nwords\nوَالفُلكِالسُّفُنِ.\nوَبَثَّنَشَرَ.\nوَتَصرِيفِ الرِّيَاحِتَقلِيبِهَا، وَتَوجِيهِهَا.\nالأَسبَابُالصِّلاَتُ.\nحَسَرَاتٍنَدَامَاتٍ.\ndeeds\nاختر واحدة من المخلوقات المذكورة في الآية، ثم استخرج ثلاث فوائد تدل على قدرة الله وحكمته فيها.\nاستخرج من القرآن ثلاثة أعمال يحبها الله سبحانه، واعمل بها اليوم.\nاكتب نوعًا من الأكل أفتى العلماء بتحريمه، وتساهل الناس فيه، مع فتوى لأحد العلماء، وأرسلها في رسالة لمن تعرف.\nguid\nمحبة المخلوقين إن زادت عن حدها قد تصل إلى شرك المحبة؛ فلا تتجاوز الحد في محبتهم مهما كانت منزلتهم.\nكثرة ذكر المحبوب دليل على شدة حبه؛ فذكر العبد لربه كثيرًا يدل على أن حبه لربه كبير.\nمن أولى خطوات الشيطان: الأكل الحرام؛ كما وقع لأبينا آدم -عليه السلام-.\nrefl\nوَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ\nووجه الآية في الفلك: تسخير الله إياها حتى تجري على وجه الماء، ووقوفها فوقه مع ثقلها. القرطبي: ٢/٤٩٤.\nبيّن وجه الآية بالفلك التي تجري في البحر؟\nوَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ١٦٤\n﴿وَتَصۡرِيفِ ٱلرِّيَٰحِ﴾: إرسالها من جهات مختلفة -وهي الجهات الأربع وما بينها- وبصفات مختلفة؛ فمنها: ملقحة للشجر، وعقيم، وصِرّ، وللنصر، وللهلاك. ابن جزي: ١/٩١.\nبيّن عظمة الله وقدرته في تصريف أنواع الرياح؟\nوَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ١٦٤\nقيل: تصريفها أنها تارة تكون لينًا، وتارة تكون عاصفًا، وتارة تكون حارةً، وتارة تكون باردةً، قال ابن عباس: \"أعظم جنود الله: الريح والماء\". البغوي: ١/١٣٢.\nما أعظم جنود الله؟\nوَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادٗا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ\nواعلم أنّ محبة الله إذا تمكنت من القلب ظهرت آثارها على الجوارح من الجدّ في طاعته، والنشاط لخدمته، والحرص على مرضاته، والتلذذ بمناجاته، والرضا بقضائه، والشوق إلى لقائه، والأنس بذكره، والاستيحاش من غيره، والفرار من الناس، والانفراد في الخلوات، وخروج الدنيا من القلب، ومحبة كل من يحبه الله، وإيثاره على كل من سواه. ابن جزي: ١/٩٢.\nما علامة تمكن المحبة من القلب؟\nإِذۡ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُواْ مِنَ ٱلَّذِينَ ٱتَّبَعُواْ وَرَأَوُاْ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ ١٦٦\nظنوا أن لها من الأمر شيئًا، وأنها تقربهم إليه، وتوصلهم إليه؛ فخاب ظنهم، وبطل سعيهم، وحق عليهم شدة العذاب، ولم تدفع عنهم أندادهم شيئًا، ولم تُغن عنهم مثقال ذرة من النفع، بل يحصل لهم الضرر منها من حيث ظنوا نفعها، وتبرأ المتبوعون من التابعين، وتقطعت بينهم الوصل التي كانت في الدنيا؛ لأنها كانت لغير الله، وعلى غير أمر الله. السعدي: ٨٠.\nما موقف المتبوعين من الأتباع يوم القيامة؟\nوَقَالَ ٱلَّذِينَ ٱتَّبَعُواْ لَوۡ أَنَّ لَنَا كَرَّةٗ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُواْ مِنَّاۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ ١٦٧\nأعمالهم التي يؤملون نفعها وحصول نتيجتها انقلبت عليهم حسرةً وندامةً... وحينئذ يتمنى التابعون أن يُردوا إلى الدنيا فيتبرأوا من متبوعيهم؛ بأن يتركوا الشرك بالله، ويقبلوا على إخلاص العمل لله. السعدي: ٨٠.\nمتى يقتنع الكفار والمشركون من الأتباع بخطأ أعمالهم؟\nكَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ ١٦٧\nقال السدي: تُرفع لهم الجنة؛ فينظرون إليها وإلى بيوتهم فيها لو أطاعوا الله تعالى، ثم تُقسم بين المؤمنين؛ فذلك حين يندمون. وأضيفت هذه الأعمال إليهم من حيث هم مأمورون بها... والحسرة أعلى درجات الندامة على شيء فائت. القرطبي: ٣/١١.\nكيف يبلغ الكفار درجة الحسرة يوم القيامة؟"],[26,"§البقرة\nwords\nيَنعِقُيَصِيحُ.\nأُهِلَّ بِهِ لِغَيرِ اللَّهِمَا ذُكِرَ عِندَ ذَبحِهِ اسمُ غَيرِ اللهِ تَعَالَى.\nغَيرَ بَاغٍغَيرَ ظَالِمٍ فِي أَكلِهِ فَوقَ حَاجَتِهِ.\nوَلاَ عَادٍغَيرَ مُتَجَاوِزٍ حُدُودَ مَا أُبِيحَ لَهُ.\nشِقَاقٍ بَعِيدٍمُنَازَعَةٍ، وَخِلاَفٍ بَعِيدٍ عَنِ الحَقِّ.\ndeeds\nأرسل رسالة تذكر فيها إخوانك بترك التقليد الأعمى، والحرص على اتباع الدليل الصحيح.\nاحمد الله تعالى بعد الأكل؛ فكم من إنسان يتمنى مثل طعامك ولا يجده.\nأرسل رسالة فيها أسماء أطعمة مشتبه فيها، وأسماء أطعمة حلال بديلًا عنها.\nguid\nالمؤمن يحرص على اتباع الدليل الصحيح من الكتاب والسنة، ولا يتبع من يتكلم بلا دليل صحيح.\nالشكر عبادة، فاحرص عليها.\nمن رحمة الله أن الأصل في الأطعمة الإباحة، أمَّا المحرم فمحصور في أصناف محدودة.\nrefl\nوَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۚ صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَعۡقِلُونَ ١٧١\nلانهماكهم في التقليد، وإخلادهم إلى ما هم عليه من الضلالة؛ لا يلقون أذهانهم إلى ما يتلى عليهم، ولا يتأملون فيما يقرر معهم؛ فهم في ذلك كالبهائم التي يُنعق عليها وهي لا تسمع إلا جرس النغمة ودوي الصوت. الألوسي: ٢/٤٢.\nلماذا وصف الله الكفار بهذه الأوصاف؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ ١٧٢\nوالأمر بالشكر عقيب النعم لأن الشكر يحفظ النعم الموجودة، ويجلب النعم المفقودة، كما أن الكفر ينفر النعم المفقودة، ويزيل النعم الموجودة. السعدي: ٨١.\nما علاقة الشكر بالنعم؟\nوَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ ١٧٢\nالشكر حقيقته: البذل من الطيب؛ فشكر كل نعمة إظهارها على حدِّها من مال أو جاه أو علم أو طعام أو شراب أو غيره، وإنفاق فضلها والاقتناع منها بالأدنى، والتجارة بفضلها لمبتغي الأجر، وإبلاغها إلى أهلها لمؤدي الأمانة؛ لأن أيدي العباد خزائن الملك الجواد. البقاعي: ١/٣١٦.\nما حقيقة الشكر؟\nإِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ١٧٣\nلمَّا كان هذا الدين يسرًا لا عسر فيه، ولا حرج، ولا جناح؛ رفع حكم هذا التحريم عن المضطر. البقاعي: ١/٣١٨.\nالشريعة صالحة لكل زمان ومكان لأنها راعت كل الأحوال، وضح ذلك من الآية.\nإِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ مَا يَأۡكُلُونَ فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ ١٧٤\n﴿وَلَا يُزَكِّيهِمۡ﴾ كما يزكي بذلك من يشاء من عباده؛ لأنهم كتموا عن العباد ما يزكيهم، وفي هذا تعظيم لذنب كتم العلم. (ولهم) مع هذا العذاب ﴿عَذَابٌ عَظِيمٌ﴾ لما أوقعوا فيه الناس من التعب بكتمهم عنهم ما يقيمهم على المحجة السهلة. البقاعي: ١/٣٢٠.\nما سبب نفي التزكية عن الذين يكتمون ما أنزل الله؟\nإِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ مَا يَأۡكُلُونَ فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ\nوسماه (قليلًا) لانقطاع مدته وسوء عاقبته، وقيل: لأن ما كانوا يأخذونه من الرِّشا كان قليلًا. وهذه الآية، وإن كانت في الأحبار؛ فإنها تتناول من المسلمين من كتم الحق مختارًا لذلك بسبب دنيا يصيبها... وفي ذكر البطون أيضًا تنبيه على جشعهم، وأنهم باعوا آخرتهم بحظهم من المطعم الذي لا خطر له. القرطبي: ٣/٤٨-٤٩.\nمن المقصود على وجه العموم بهذه الآية؟ وما دلالة قوله: ﴿فِي بُطُونِهِمۡ﴾؟\nفَمَآ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ ١٧٥\nأي: فما أدومهم لعمل المعاصي التي تفضي بهم إلى النار. ابن كثير: ١/١٩٦.\nكيف وُصِفُوا بالصبر على النار وهم لم يدخلوها بعد؟"],[27,"§البقرة\nwords\nالبِرَّالتَّوَسُّعَ فِي فِعلِ الخَيرِ وَالطَّاعَةِ.\nوَابنَ السَّبِيلِالمُسَافِرَ المُحتَاجَ المُنقَطِعَ عَن أَهلِهِ.\nوَفِي الرِّقَابِفِي تَحرِيرِ الرِّقَابِ مِنَ الرِّقِّ وَالأَسرِ.\nالبَأسَاءِالفَقرِ.\nوَالضَّرَّاءِالمَرَضِ.\nوَحِينَ البَأسِحِينَ شِدَّةِ القِتَالِ.\nتَرَكَ خَيرًاتَرَكَ مَالًا كَثِيرًا.\ndeeds\nضع جدولًا زمنيًا لتوزيع صدقاتك وهداياك ممَّا تحب على الأصناف المذكورة في الآية.\nاذهب إلى الصلاة مبكرًا.\nبادر بكتابة وصيتك بعد استشارة من له خبرة في ذلك.\nguid\nاجمع بعض أعمال القلوب، ثم تعرف على كيفية تحقيقها في قلبك.\nالمؤمن وفِيٌّ بالعهد لا يُخلفه، بل هو أحرص شيء عليه، وإنمَّا ينقض العهد المنافق.\nالقصاص من أسباب استقرار المجتمعات وأمانها.\nrefl\nوَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ\nذوي القربى وما بعده: ترتيب بتقديم الأهم فالأهم والأفضل؛ لأنّ الصدقة على القرابة صدقة وصلة؛ بخلاف من بعدهم، ثم اليتامى لصغرهم وحاجتهم، ثم المساكين للحاجة خاصة، وابن السبيل الغريب، وقيل: الضعيف، والسائلين وإن كانوا غير محتاجين. ابن جزي: ١/٩٥.\nفي الآية الاهتمام بالأولويات وبالأهم فالمهم، وضح ذلك\nوَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ\nفمن أخرجه مع حبه له تقربًا إلى الله تعالى كان هذا برهانًا لإيمانه. ومن إيتاء المال على حبه: أن يتصدق وهو صحيح شحيح، يأمل الغنى، ويخشى الفقر، وكذلك إذا كانت الصدقة عن قلة كانت أفضل؛ لأنه في هذه الحال يحب إمساكه لما يتوهمه من العدم والفقر، وكذلك إخراج النفيس من المال، وما يحبه من ماله. السعدي: ٨٣.\nاذكر شيئًا من صور إيتاء المال على حبه.\nوَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ ١٧٧\nأي: هؤلاء الذين اتصفوا بهذه الصفات هم الذين صدقوا في إيمانهم؛ لأنهم حققوا الإيمان القلبي بالأقوال والأفعال، فهؤلاء هم الذين صدقوا، وأولئك هم المتقون؛ لأنهم اتقوا المحارم، وفعلوا الطاعات. ابن كثير: ١/١٩٨.\nما علامة صدق الإيمان؟\nوَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ ١٧٧\nوهذا من باب الترقي في الصبر من الشديد إلى الأشد؛ لأن الصبر على المرض فوق الصبر على الفقر، والصبر على القتال فوق الصبر على المرض. الألوسي: ٢/٤٨.\nهل تتفاوت درجات الصبر؟\nفَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنٖۗ\nوصية العافي بأن لا يُشدد في طلب الدية على المعفو له، وينظره إن كان معسرًا، ولا يطالبه بالزيادة عليها، والمعفو بأن لا يمطل العافي فيها، ولا يبخس منها، ويدفعها عند الإمكان. الألوسي: ٢/٥٠.\nبماذا وصى الله الطرفين عند أخذ الدية أو العفو؟\nوَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ ١٧٩\n(ولكم في القصاص حياة) بمعنى قولهم: \"القتل أنفى للقتل\"؛ أي: إن القصاص يردع الناس عن القتل، وقيل: المعنى أن القصاص أقل قتلًا؛ لأنه قتل واحد بواحد، بخلاف ما كان في الجاهلية من اقتتال قبيلتي القاتل والمقتول حتى يقتل بسبب ذلك جماعة. ابن جزي: ١/٩٦.\nكيف يكون في القصاص حياة؟\nفَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُ\nفمن بدَّل الوصية وحرفها؛ فغيَّر حكمها، وزاد فيها أو نقص، ويدخل في ذلك الكتمان لها بطريق الأولى؛ ﴿فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ﴾: قال ابن عباس وغير واحد: وقد وقع أجر الميت على الله، وتعلَّق الإثم بالذين بدَّلوا ذلك. ابن كثير: ١/٢٠١.\nحسن اختيار الناظر على الوصية أمر في غاية الأهمية، وضح ذلك من الآية."],[28,"§البقرة\nwords\nجَنَفًامَيلًا عَنِ الحَقِّ خَطَأً وَجَهلًا.\nتَطَوَّعَ خَيرًازَادَ فِي الفِديَةِ بَدَلَ الصِّيَامِ.\nفَليَستَجِيبُوا لِيفَليُطِيعُونِي.\nيَرشُدُونَيَهتَدُونَ.\ndeeds\nأصلح اليوم بين متخاصمين، أو متداينين؛ متذكرًا أهمية الصلح.\nتعاهد نفسك بصيام ثلاثة أيام من كل شهر ولو متفرقة؛ لأن ذلك ضرورة لصلاح القلب ونماء التقوى فيه.\nحدد مطلبًا كبيرًا ترجوه في حياتك، ثم صم يومًا، وألِحَّ على الله بالدعاء فيه، محسنًا الظن بالله تعالى.\nguid\nمن حكم الصيام: الإعانة والتدريب على تقوى الله تعالى.\nفي الصيام -واجبًا كان أو مندوبًا- أنواعٌ من الخير للمؤمن يعلمها أو لا يعلمها.\nبالدعاء تحصل الهداية والرشاد.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ ١٨٣ أَيَّامٗا مَّعۡدُودَٰتٖۚ\nوالقصد بقوله: ﴿كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ﴾، وبقوله: ﴿أَيَّامًا مَّعۡدُودَٰتٍۚ﴾: تسهيل الصيام على المسلمين، وملاطفة جميلة. ابن جزي: ١/٩٥.\nجمع سبحانه في شرعه بين الحكمة والرحمة، وضح ذلك من خلال الآية.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ\nلأنه من الشرائع والأوامر التي هي مصلحة للخلق في كل زمان، وفيه تنشيط لهذه الأمة بأنه ينبغي لكم أن تُنافسوا غيركم في تكميل الأعمال، والمسارعة إلى صالح الخصال، وأنه ليس من الأمور الثقيلة التي اختصَّيتم بها. السعدي: ٨٦.\nما الذي يُفاد من الإخبار بأن هذا الصيام كان فرضًا على من قبلنا؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ ١٨٣\nأي: كي تحذروا المعاصي؛ فإن الصوم يُعقم الشهوة التي هي أمها، أو يكسرها،... قال لنا رسول الله -صلى الله تعالى عليه وسلم-: «يا معشر الشباب، من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم؛ فإنه له وجاء». الألوسي: ٢/٥٧.\nكيف يؤدي الصيام إلى التقوى؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ ١٨٣\n«يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى: كُلُّ عَمَلِ ابنِ آدَمَ لَهُ إِلا الصَّومُ فَإِنَّهُ لِي وَأَنَا أَجزِي بِهِ...» الحَدِيثَ؛ خصّ الصوم بأنه له -وإن كانت العبادات كلها له- لأمرين باين الصوم بهما سائر العبادات؛ أحدهما: أن الصوم يمنع من ملاذ النفس وشهواتها ما لا يمنع منه سائر العبادات إلا الصلاة. الثاني: أن الصوم سرّ بين العبد وربه، لا يظهر إلا له؛ فلذلك صار مختصًّا به، وما سواه من العبادات ظاهر، ربما فعله تصنُّعًا ورياءً، فلهذا صار أخصّ بالصوم من غيره. القرطبي: ٣/١٢٣.\nبيّن فضل عبادة الصوم على غيرها من العبادات.\nوَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ\nومن أعظم أسراره أنه لمَّا كان العيد محل فرح وسرور، وكان من طبع النفس تجاوز الحدود لما جُبلت عليه من الشَّرَهِ -تارة غفلةً، وتارة بغيًا- أمر بالتكبير. البقاعي: ١/٣٤٥.\nلماذا أمر الله بالتكبير في ليلة عيد رمضان؟\nوَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ\nذكر في هذه الآية أنه -جل وعلا- قريب يجيب دعوة الداعي، وبيَّن في آية أخرى تعليق ذلك على مشيئته -جل وعلا-؛ وهي قوله: ﴿فَيَكۡشِفُ مَا تَدۡعُونَ إِلَيۡهِ إِن شَآءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ﴾ [الأنعام: ٤١]، وقال بعضهم: التعليق بالمشيئة في دعاء الكفار كما هو ظاهر سياق الآية، والوعد المطلق في دعاء المؤمنين؛ وعليه فدعاؤهم لا يُرد: إما أن يُعطَوا ما سألوا، أو يُدَّخَر لهم خيرٌ منه، أو يُدفَع عنهم من السوء بقدره. الشنقيطي: ١/٧٤.\nما الفرق بين دعاء المؤمن ودعاء الكافر من حيث الإجابة؟\nوَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ ١٨٦\nوفي هذه الآية إيماء إلى أن الصائم مرجوُّ الإجابة، وإلى أن شهر رمضان مرجوَّةٌ دعواته، وإلى مشروعية الدعاء عند انتهاء كل يوم من رمضان. ابن عاشور: ٢/١٧٩.\nما الحكمة من دخول آية الدعاء بين آيات الصيام؟"],[29,"§البقرة\nwords\nالرَّفَثُالجِمَاعُ.\nلِبَاسٌسَكَنٌ، وَسِترٌ عَنِ الحَرَامِ.\nتَختَانُونَتَخُونُون، فَتَقَعُونَ فِي المَعصِيَةِ\nبَاشِرُوهُنَّجَامِعُوهُنَّ.\nحُدُودُ اللَّهِمُحَرَّمَاتُهُ وَمَنهِيَّاتُهُ.\nوَتُدلُواتَدفَعُوا.\ndeeds\nاكتب خمسة من أضرار الرشوة على الفرد والمجتمع، وأرسلها في رسالة.\nتعاون مع غيرك لاسترداد حق مسلم أُخذ بسبب الرشوة.\nتذكر مسلمًا أخطأت عليه، واعتذر منه ولو برسالة؛ حتى يحبك الله سبحانه.\nguid\nالغاية من إنزال الشرائع ووضع الحدود تقوى الله -عز وجل-.\nلا تقترب من الشبهات فتقع في الحرام.\nاحذر أكل أموال الناس بالباطل.\nrefl\nوَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ\nوفي إباحته تعالى جواز الأكل إلى طلوع الفجر دليلٌ على استحباب السحور؛ لأنه من باب الرخصة، والأخذ بها محبوب. ابن كثير: ١/٢١٠.\nكيف يستدل بالآية على استحباب السحور؟\nوَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ\nوفي ذكره تعالى الاعتكاف بعد الصيام إرشادٌ وتنبيهٌ على الاعتكاف في الصيام، أو في آخر شهر الصيام. ابن كثير: ١/٢١٣.\nما الذي يدل عليه ذكر الاعتكاف بعد الصيام؟\nوَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ\nفلا يكون الاعتكاف إلا في المساجد باتفاق العلماء؛ كما قال تعالى: ﴿وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِ﴾، لا يكون الاعتكاف لا بخلوة، ولا غير خلوة؛ لا في غار، ولا عند قبر، ولا غير ذلك مما يقصد الضالُّون السفر إليه والعكوف عنده؛ كعكوف المشركين على أوثانهم. ابن تيمية: ١/٤٤٨-٤٤٩.\nهل يصح اعتكاف في غير المساجد؟ استخرج الدليل من الآية.\nتِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ\nأبلغ من قوله: فلا تفعلوها؛ لأن القربان يشمل النهي عن فعل المحرم بنفسه، والنهي عن وسائله الموصلة إليه، والعبد مأمور بترك المحرمات، والبعد منها غاية ما يمكنه، وترك كل سبب يدعو إليها. السعدي: ٨٧-٨٨.\nلماذا نهى الله عن قربان حدوده المحرمة بدلًا من النهي عن فعلها؟\nوَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ ١٨٨\nلما ذكر سبحانه الصيام وما فيه؛ عقبه بالنهي عن الأكل الحرام المفضي إلى عدم قبول عبادته من صيامه واعتكافه. الألوسي: ٢/٦٩.\nما علاقة النهي عن أكل الحرام بالصيام؟\nوَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ ١٨٨\nلا تصانعوا بأموالكم الحكام وترشوهم؛ ليقضوا لكم على أكثر منها... اتفق أهل السنة على أن من أخذ ما وقع عليه اسم مال -قل أو كثر- أنه يفسق بذلك، وأنه محرّم عليه أخذه. القرطبي: ٣/٢٢٦.\nمن محافظة الصائم على صومه ابتعاده عن الرشوة، وضح ذلك من سياق الآيات.\nوَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ١٨٩\nمن اتقى الله تعالى تفجرت ينابيع الحكمة من قلبه، وانكشفت له دقائق الأسرار حسب تقواه. الألوسي: ٢/٧٤.\nما ثمرة التقوى؟"]])